Hook.Script:
if (typeof work === "undefined") {
	work = system.newEntry();
}

invokeHook("onshutdownrequest", work);

endOfFlowHandling(isSync)

if (typeof work === "undefined") {
	work = system.newEntry();
}

invokeHook("onfailure", work);

endOfFlowHandling(isSync)

if (typeof work === "undefined") {
	work = system.newEntry();
}

invokeHook("onsuccess", work);

endOfFlowHandling(isSync);

initUtils();

prepareReport(); // prepare carrier of operation statistics

//
// Print Flow report
//
logmsg("\n" + FlowReport() + "\n")

typeOfEntry = "* unknown *"

changeDetType = getProperty("source.changeDetectionType","delta").toLowerCase()
if (preserveContainers)
	containerMsg = " " + resource.getString("LDAPSYNC.MIRRORING.HIERARCHY")
else
	containerMsg = " " + resource.getString("LDAPSYNC.FLATTENING.HIERARCHY")

logmsg("--> " + resource.getString("LDAPSYNC.STARTING.MIGRATION") + ": " + flowKey + " - " + containerMsg)
cont2Migrate = getProperty("source.containersToMigrate", null);
if (cont2Migrate !== null) {
	logmsg("-->   " + resource.getString("LDAPSYNC.CONTAINERS.TO.MIGRATE") + ":\n" + cont2Migrate);
}	
cont2Skip = getProperty("source.containersToSkip", null);
if (cont2Skip !== null) {
	logmsg("-->   " + resource.getString("LDAPSYNC.CONTAINERS.TO.SKIP") + ":\n" + cont2Skip)
}

stateKey = "";
abortFlow = false;
storeFactory = com.ibm.di.store.StoreFactory().getDefaultPropertyStore();

Logger.parameter:
@SUBSTITUTE{javascript opEntry = task.getOpEntry()
if (opEntry != null) {
	flowKey = opEntry.getString("flowKey")
	folder = opEntry.getString("global.logDirectory")
	if (folder == null) {
		folder = opEntry.getString(flowKey + ".global.logDirectory")
	}
}

if (folder == null) {
	folder = opEntry.getString("global.logDirectory")
	if (folder == null) {
		folder = "LDAPSync/logs"
	}
}

logFile = folder + "/" + task.getShortName() + "_server.log"

return logFile}

Script.parameter:
abortFlow = false;
endOfData = false;
lastStateKeyReset = "*initial*";
targetTCB = null;

retEntry = invokeHook("prolog", work);

if (retEntry !== null) {
	abortFlow = "true".equalsIgnoreCase(retEntry.getString("$stopFlow"));
}

if (isSync) {
	lostFileName = "EntriesNotSynchronized";
} else {
	lostFileName = "EntriesNotMigrated";
}

if (simulate) {
	lostFileName = lostFileName + "_simulate";
}

suffixStr = ""

if (true /*preserveContainers || handleType.group == true*/) {

	if (targetRootSuffix != null && targetRootSuffix.trim().length != 0) {
		suffixStr = targetRootSuffix
	}

	try {
		if (!preserveContainers) {
			if (handleType.person == true) {
				if (targetSuffixForUsers == null || targetSuffixForUsers.trim().length == 0) {
					addToStats(flowKey, "error", "error");
					throw resource.getString("LDAPSYNC.PROPERTY.NOT.SET") + ": target.suffixForUsers. "
							+ resource.getString("LDAPSYNC.YOU.MUST.SPECIFY.WHERE.PERSON.ENTRIES.ARE.TO.BE.FLATTENED.UNDER")
				}
				if (suffixStr != "")
					suffixStr += ";"
				suffixStr += targetSuffixForUsers
			}	
			if (handleType.group == true) {
				if (targetSuffixForGroups == null || targetSuffixForGroups.trim().length == 0) {
					addToStats(flowKey, "error", "error");
					throw resource.getString("LDAPSYNC.PROPERTY.NOT.SET") + ": target.suffixForGroup. "
							+ resource.getString("LDAPSYNC.YOU.MUST.SPECIFY.WHERE.GROUP.ENTRIES.ARE.TO.BE.FLATTENED.UNDER")
				}
				if (suffixStr != "")
					suffixStr += ";"
				suffixStr += targetSuffixForGroups
			}	
		}
	} catch (ex) {
		throw where() + " - " + ex
	}
}

suffixMap = new java.util.concurrent.ConcurrentHashMap();
suffixes = system.splitString(suffixStr.toLowerCase(), ";");

for (suffixCnt = 0; suffixCnt < suffixes.length; suffixCnt++) {
	container = suffixes[suffixCnt];

	try {
		ldapName = new javax.naming.ldap.LdapName(container);
	} catch (ex) {
		throw where() + " - " + resource.getString("LDAPSYNC.ERROR.REPARSING.CONTAINER.DN")
					+ ": " + ex + " - DN: " + container;
	}	
	rdns = ldapName.getRdns();
	rdnSize = rdns.size();


	for (i = rdnSize; i > 1; i--) {
		if (i < rdnSize) {
			ldapName.remove(i);
		}

		subRDNs = ldapName.getRdns();
		rdn = subRDNs[0].toString();
		for (j = 1; j < subRDNs.size(); j++) {
			rdn += "," + subRDNs[j].toString();
		}

		if (!suffixMap.containsKey(rdn)) {
			e = system.newEntry();
			e.dn = ldapName.toString();
			e.rdn = rdns[i-1].getType();
			e.rdnValue = rdns[i-1].getValue();
			e.typeOfEntry = containerRDN.get(e.getString("rdn"));
			suffixMap.put(rdn, e);
		}
	}
}

suffixes = suffixMap.keySet().toArray();
java.util.Arrays.sort(suffixes);
suffixCnt = 0;

suffixKey = suffixes[suffixCnt];
containerEntry = suffixMap.get(suffixKey);
useRDN = containerEntry.getString("rdn");
typeOfEntry = containerEntry.getString("typeOfEntry");

work.removeAllAttributes()
work[useRDN] = containerEntry.getString("rdnValue");
work["$objectClass"] = typeOfEntry;
work["$translatedDN"] = containerEntry.getString("dn");
work["$targetLDAPDN"] = containerEntry.getString("dn");

Hook.Script:
if (typeof opEntry !== "undefined" && opEntry != null) {
	opEntry["$ctr"] = null;
	opEntry["$alFC"] = null;
}

logmsg("-----> " + resource.getString("LDAPSYNC.CREATING.SUFFIX.IN.TARGET") + ": " + work.getString("$translatedDN"));

conn[useRDN] = work[useRDN];
conn.objectClass = typeOfEntry;

errmsg = error.getString("message");
if (errmsg !== null && 
	(errmsg.indexOf("error code 32") >= 0 || // no such object
	 errmsg.indexOf("error code 53") >= 0)) { // no global superior knowledge 
	error.status = "ok";
	error.exception = null;
	error.message = null;
	return; // do nothing
}

defaultErrorHandling("ERROR", true);

abortFlow = true;

change = false;
if (typeof(work) != "undefined" && work != null) {
	work["$status"] = "failed";
	work["$error"] = error;
}	
defaultInitErrorHandling("ERROR", true);

Script.parameter:
if (simulate) {
	logmsg("WARN", resource.getString("LDAPSYNC.LDAPSYNC.CAN.NOT.BE.SIMULATED.PLEASE.CHANGE.THE.SIMULATE.PROPERTY"))
	logmsg("WARN", " - " + resource.getString("LDAPSYNC.PLEASE.SET.THE.FOLLOWING.PROPERTY.SIMULATEFALSE"))
	logmsg("WARN", "   " + resource.getString("LDAPSYNC.OR.USE.THE.COMMANDLINE.OPTION.0.ACTUAL"))

	system.exitFlow()
}

defaultALName = new java.util.concurrent.ConcurrentHashMap()
defaultALName.put("sun", "ReadSunChange") 
defaultALName.put("ad", "ReadADChange") 
defaultALName.put("tds", "ReadTDSChange")
defaultALName.put("sds", "ReadTDSChange")
defaultALName.put("delta", "ReadEntries")

defaultJoinALName = new java.util.concurrent.ConcurrentHashMap()
defaultJoinALName.put("container", "JoinEntry")
defaultJoinALName.put("person", "JoinEntry")
defaultJoinALName.put("group", "JoinEntry")

joinALFC = new java.util.concurrent.ConcurrentHashMap();

// force roll of Entry Lost file
writeLostEntry(null, lostFileName)

checkTypes = ["container","person","group"]

types = []
for (i = 0; i < checkTypes.length; i++) {
	thisType = checkTypes[i]
	if (thisType == "container" && !preserveContainers && !targetIsLDAP) {
		continue;
	}
	if (handleType[thisType] == true) {
		types[types.length] = thisType
	}
}

typeCnt = 0

typeOfEntry = types[typeCnt]

currentType = typeOfEntry

opEntry["$deltaKey"] = getProperty("source.userRDN");
if (!"delta".equalsIgnoreCase(changelogType)) {
	opEntry["$deltaStore"] = connectorParam("source.ldap.stateKey", "statekey");
} else {
	opEntry["$deltaStore"] = connectorParam("source.ldap.stateKey", "statekey") + "_" + typeOfEntry.substring(0,1).toUpperCase();
}	
opEntry["$typeOfEntry"] = typeOfEntry;

if ("delta".equalsIgnoreCase(changelogType)) {
	opEntry["$enableDelta"] = (!simulate).toString();
	if (deBug) logmsg("--@@-> Delta Store: " + opEntry["$deltaStore"])
} else {
	typeCnt = types.length // stop after this single cycle
}

ALName = getALName("source.delta." + typeOfEntry + ".AL",null)
if (ALName == null || ALName.trim().length == 0) {
	ALName = getALName("source.read." + typeOfEntry + ".AL",defaultALName.get(changelogType))
}

Branch.ScriptCondition:
if (!"delta".equals(changelogType)) {
	return true
} else
if ("container".equals(typeOfEntry) && handleType.container == true && preserveContainers) {
	return true
} else {
	return (handleType[typeOfEntry] == true)
}

Script.parameter:
checkTypes = ["container","person","group"];

defaultALName = new java.util.concurrent.ConcurrentHashMap();
defaultALName.put("container", "ReadContainers");
defaultALName.put("person", "ReadPersons");
defaultALName.put("group", "ReadGroups");

defaultJoinALName = new java.util.concurrent.ConcurrentHashMap();
defaultJoinALName.put("person", "JoinEntry");

joinALFC = new java.util.concurrent.ConcurrentHashMap();

OnlyInitializeGroupDeltaStore = false;
types = [];
for (i = 0; i < checkTypes.length; i++) {
	thisType = checkTypes[i];
	if (thisType == "container" && !preserveContainers && !targetIsLDAP) {
		continue;
	} else
	if (thisType == "group" && filterOnGroups) {
		if (cloudSync) {
			continue;
		}

		OnlyInitializeGroupDeltaStore = !(true == handleType["group"]);
		handleType["group"] = true;
	}

	if (handleType[thisType] == true) {
		types.push(thisType);
	}
}

writeLostEntry(null, lostFileName);

changelogType = getProperty("source.changeDetectionType","delta").toLowerCase();

typeCnt = 0;
abortFlow = false;
endOfData = false;

typeOfEntry = types[typeCnt]

currentType = typeOfEntry

opEntry["$deltaKey"] = getProperty("source.userRDN");
if (!"delta".equalsIgnoreCase(changelogType)) {
	opEntry["$deltaStore"] = connectorParam("source.ldap.stateKey", "statekey");
} else {
	opEntry["$deltaStore"] = connectorParam("source.ldap.stateKey", "statekey") + "_" + typeOfEntry.substring(0,1).toUpperCase();
}	
opEntry["$typeOfEntry"] = typeOfEntry;

if ("delta".equalsIgnoreCase(changelogType)) {
	opEntry["$enableDelta"] = (!simulate).toString();
	if (deBug) logmsg("--@@-> Delta Store: " + opEntry["$deltaStore"])
}

ALName = getALName("source.read." + typeOfEntry + ".AL",defaultALName.get(typeOfEntry));

endOfData = false;

cdType = getProperty("source.changeDetectionType","")

if (!simulate) {
	if ("delta".equalsIgnoreCase(cdType) || "ad".equalsIgnoreCase(cdType)) {
		stateKey = opEntry.getString("$deltaStore");
		if (typeof(lastDeltaStateKeyReset) == "undefined") {
			lastDeltaStateKeyReset = "";
		}

		if (!stateKey.equals(lastDeltaStateKeyReset)) {
			logmsg("INFO", resource.getString("LDAPSYNC.RESETTING.CHANGE.DETECTION.STATE.FOR.FLOW") + ": " + flowKey + " (" + stateKey.toUpperCase() + ")")

			tableName = "IDI_DS_" + stateKey.toUpperCase()
			try {
				com.ibm.di.store.StoreFactory.dropTable(tableName)
			} catch (ex) {
				if (String(ex).indexOf("-204") < 0 && String(ex).indexOf("SyntaxError") < 0) {
					logmsg("WARN", resource.getString("LDAPSYNC.UNABLE.TO.DELETE.DELTA.STORE.TABLE") + ": " + tableName 
							+ " - " + ex)
					addToStats(flowKey, "warn", "warn");
				}	
			}
			lastDeltaStateKeyReset = stateKey;
		}	
	} 

	if (!"delta".equalsIgnoreCase(cdType)) {
		stateKey = connectorParam("source.ldap.stateKey", "statekey");
		if (typeof(lastStateKeyReset) == "undefined") {
			lastStateKeyReset = "";
		}

		if (!stateKey.equals(lastStateKeyReset)) {
			logmsg("INFO", resource.getString("LDAPSYNC.RESETTING.CHANGE.DETECTION.STATE.FOR.FLOW") + ": " + flowKey + " (" + stateKey.toUpperCase() + ")")

			storeFactory.removeProperty(stateKey)
			lastStateKeyReset = stateKey;
		}	
	}	
}

// For AD, Sun and SDS (& changelog compatible endpoints), set the change state
// to the last committed changenumber/USN
//
if (typeof(lastStateKeySet) == "undefined") {
	lastStateKeySet = "";
}

if (!lastStateKeySet.equals(stateKey) && "person".equals(typeOfEntry)) {
	lastStateKeySet = stateKey;	

	lastChangeState = work.getString("$lastChangeState");

	if (lastChangeState != null) {
		logmsg("INFO", resource.getString("LDAPSYNC.SETTING.CHANGE.STATE") + " (" + stateKey.toUpperCase() + "): " + lastChangeState)
		storeFactory.setProperty(stateKey, lastChangeState)	
	}
}

// This is to prevent re-init of the Read next entry AL when entry type changes.
// Although this is necessary for migration, it should not happen during sync
lastType = currentType

if (abortFlow) {
	addToStats(flowKey, "error", "error");
	logmsg("ERROR", resource.getString("LDAPSYNC.USER.ABORT"));
	throw resource.getString("LDAPSYNC.USER.ABORT");
}

Hook.Script:
var flowKey = getProperty("global.flows");
var hookName = getProperty("$hookName");

function opEntryParams() {
	var e = task.getOpEntry();
	var s = java.lang.StringBuffer();
	var names = e.getAttributeNames();
	java.util.Arrays.sort(names);
	for (var n in names) {
		if (n.indexOf(flowKey) < 0) {
			s.append("opEntry:   " + e.getAttribute(n).toString() + "\n");
		}
	}

	return s.toString();
}

function tcbParams() {
	var e = task.getTCB();
	var s = java.lang.StringBuffer();
	var names = e.getAttributeNames();
	java.util.Arrays.sort(names);
	for (var n in names) {
		s.append("TCB:   " + e.getAttribute(n).toString() + "\n");
	}

	return s.toString();
}

function iwe() {
	var s = java.lang.StringBuffer();
	var e = work;
	var names = e.getAttributeNames();
	java.util.Arrays.sort(names);
	for (var n in names) {
		s.append("IWE:   " + e.getAttribute(n).toString() + "\n");
	}

	return s.toString();
}

