	setException(ex,"writeToTarget")
}

initUtils();

callCount = 0;

// get group attributes for map file in order to limit lookups to not include member attribute
try {
	groupReturnAttributes = "";
	mapFile = getProperty("target.group.mapFile", configDirectory + "/group.map")
	if (mapFile === null || mapFile.length == 0)
		mapFile = "group.map"
	if (mapFile.indexOf("/") < 0 && mapFile.indexOf("\\") < 0)
		mapFile = configDirectory + "/" + mapFile
	file = system.openFileForInput(mapFile);
	do{
		line = file.readLine();
		if(line != null && line.indexOf("=")>0){
			parts = system.splitString(line,"=");
			pos = parts[0].indexOf("{");
			if(pos > 0){
				parts[0] = parts[0].substring(0,pos);
			}
			if(parts[0].toLowerCase().indexOf("member") > 0){
				continue;
			}
			groupReturnAttributes += parts[0]+"\n";
		}
	}while(line != null)
	file.close();
} catch (ex) {
	throw where() + " " + resource.getString("LDAPSYNC.ERROR.READING.GROUP.MAP.FILE") + " (" + mapFile + "): " + ex
}	
groupReturnAttributes += "\ncn\nobjectClass\n" + auxLinkedGUIDSourceAttribute + "\n"

// get group attributes for map file in order to limit lookups to not include member attribute
try {
	personReturnAttributes = "";
	mapFile = getProperty("target.person.mapFile", "person.map")
	if (mapFile === null || mapFile.length == 0)
		mapFile = "person.map"
	if (mapFile.indexOf("/") < 0 && mapFile.indexOf("\\") < 0)
		mapFile = configDirectory + "/" + mapFile
	file = system.openFileForInput(mapFile);
	do{
		line = file.readLine();
		if(line != null && line.indexOf("=")>0){
			parts = system.splitString(line,"=");
			pos = parts[0].indexOf("{");
			if(pos > 0){
				parts[0] = parts[0].substring(0,pos);
			}
			personReturnAttributes += parts[0]+"\n";
		}
	}while(line != null)
	file.close();
	personReturnAttributes += "+\n"
								+ auxLinkedDNAttribute + "\n"
								+ auxLinkedGUIDAttribute + "\n"
								+ "ibm-ptaLinkAttribute\n"
								+ "ibm-ptaLinkValue\n";
} catch (ex) {
	throw where() + " " + resource.getString("LDAPSYNC.ERROR.READING.PERSON.MAP.FILE") + " (" + mapFile + "): " + ex
}	

// simulate by default
simulate = !"false".equalsIgnoreCase(getProperty("simulate"))

progressReport = 0

progressReportStr = main.commandLineParam("1")
if (progressReportStr !== null) {
	try {
		progressReport = system.toInt(progressReportStr)
	} catch (ex) {
		progressReport = 0
	}
}

if (progressReport == 0) {
	progressProp = getProperty("global.showProgressCount")
	if (progressProp !== null) {
		try {
			progressReport = system.toInt(progressProp)
		} catch (ex) {
			progressReport = 0
		}
	}	
}

if (targetRootSuffix !== null) {
	targetRootSuffix = cleanDN(targetRootSuffix, "target.ldap.searchBase property is not set");
}	
if (targetSuffixForUsers !== null) {
	targetSuffixForUsers = cleanDN(targetSuffixForUsers);
}	
if (targetSuffixForGroups !== null) {
	targetSuffixForGroups = cleanDN(targetSuffixForGroups);
}

targetRootSuffix = targetRootSuffix || "o=unspecifiedTargetSuffix";
targetSuffixForUsers = targetSuffixForUsers || "o=unspecifiedTargetSuffixForUsers"
targetSuffixForGroups = targetSuffixForGroups || "o=unspecifiedTargetSuffixForGroups"

// set dummyMember value, used to add Group entries to SDS with no members
dummyMember = "cn=dummyMemberFromFDS";

if (simulate) {
	logFilename = flowKey + "_GroupMembersMissing_simulate";
} else {
	logFilename = flowKey + "_GroupMembersMissing";
}	
logFileFullname = logFilepath + "/" + logFilename + ".log.temp"
try {
	file = openOutputFile(logFileFullname)
	logFiles.setAttribute(logFileFullname, file)
	file.close()
} catch (ex) {
	logmsg("ERROR","" + ex + " - " + resource.getString("LDAPSYNC.ERROR.CREATING.MISSING.MEMBERS.FILE") 
					+ ": " + logFileFullname)
}


ptaAttributes = ["ibm-ptalinkattribute", "ibm-ptalinkvalue"]

targetLDAP = null;

Script.parameter:
work["$writeStatus"] = "failed";
work.removeAttribute("$error");
work.removeAttribute("$errorLogged");

if (doTiming) timing("writetotarget - init cycle")

// if this is the first cycle, prepare the cloned source LDAP Connector
// and set up some variables
//
if((typeof(firstTime) == "undefined")){
	firstTime = false;

	if (simulate)
		logmsg("*** " + resource.getString("LDAPSYNC.SIMULATED.RUN.NO.DATA.WILL.BE.MODIFIED") + " ***")

	if(!preserveContainers){
		msg = resource.getString("LDAPSYNC.PROPERTY.IS.NOT.SET")
		if (targetSuffixForUsers == null) {
			logmsg("FATAL", msg + ": target.suffixForUsers")
			throw where() + " - " + msg + ": target.suffixForUsers"
		}	
		if (targetSuffixForGroups == null) {
			logmsg("FATAL", msg + "target.suffixForGroups")
			throw where() + " - " + msg + "target.suffixForGroups"
		}	
	}	
	if (progressReport > 0 && !changeDetection) {
		logmsg("* " + resource.getString("LDAPSYNC.COUNT.FOR.PROGRESS.DISPLAY") + ": " + progressReport)
	}
}

// Set boolean flag to false
foundInTarget = false;

// Try to figure out entry type based on RDN
//
useSuffix = targetRootSuffix;
oc = work.getAttribute("objectClass")
typeOfEntry = entryType(oc)
cn = work.getString("cn");

if (cloudSync) {
	useRDN = sourceRDNAtt
	readRDN = useRDN
}
else 
if ("person".equals(typeOfEntry)) {
	useRDN = targetUserRDN
	readRDN = sourceUserRDN
}
else
if ("group".equals(typeOfEntry)) {
	useRDN = "cn"
	readRDN = useRDN
}
else 
if ("unknown".equals(typeOfEntry)){
	useRDN = "???"
	readRDN = useRDN
}
else {	
	// if type is unknown then this caught below, else it's a container so use the source RDN
	useRDN = sourceRDNAtt
	readRDN = useRDN
}

if (readRDN.equalsIgnoreCase(sourceRDNAtt)) {
	rdnValue = sourceRDNValue
	encodeRDN = false // already encoded
} else {
	rdnValue = getRDN(work, readRDN);
}	

//
// If source is AD then deleted entries are tombstones and are missing needed attributes
//    Also, the source rdn may have changed, and that could affect the target
//    Or the entry could have been moved in the AD DIT (moddn)
//    So, except for 'add' changes we always have to look up AD entries in the target based on objectGUID
//	  as the sourceGUID.
//
// For Domino the sourceGUID will be the UNID Attribute.
//
// For non-AD sources, changes to rdn or parent container require a lookup in the Target using the old dn
//
// For 'add' and 'modify' from non-AD changelog, there may not be all needed attributes in work
//    Needed attributes are for example: targetUserRDN and objectClass
//    Then we have to look up the entry in the source
//
// In general, for non-delete changes, we look up the entry in the target system
//
sourceEntry = null
if (targetLDAP != null && 
	("unknown".equals(typeOfEntry) || 
	 cn == null ||
	 rdnValue == null || 
	 newSuperior != null ||
	 newrdn != null ||
	 "delete".equals(deltaOperationTag) ||
	 (filterOnGroups || filterOnAttributes)) ) {
	if (changeDetection)	{
		// If entry coming from AD use sourceGUID to locate the entry in the target
		if (sourceGUID !== null && sourceGUID.length > 0) {
			if (targetEntry != null) {
				// the entry already read from the target in 'Prepare for filtering' Script
				sourceEntry = targetEntry
			} else {
				sc = system.newSearchCriteria()
				sc.addCriteria(auxLinkedGUIDAttribute, sc.EXACT, sourceGUID);
				targetLDAP.setParam("ldapReturnAttributes", auxLinkedDNAttribute +"\n" + auxLinkedGUIDAttribute + "\nsn\ncn\nobjectClass\n"+containerRDNs+targetUserRDN);
				try {
					sourceEntry = targetLDAP.findEntry(sc);
				} catch (ex) {
					sourceEntry = null
				}

				if (deBug) logmsg("-@@-->> target lookup for AD entry using " + auxLinkedGUIDAttribute + " = " + sourceGUID +
								(sourceEntry == null ? " - failed" : " - success"))
			}	

			foundInTarget = (sourceEntry !== null);

			if (sourceEntry != null && newrdn == null) {
				targetLDAPDN = sourceEntry.getString("$dn")
				if (rdnValue == null) {
					rdnValue = getRDN(sourceEntry, readRDN);
				}	

				if ("modify".equals(deltaOperationTag)) {
					previousDN = sourceEntry.getString(auxLinkedDNAttribute)
					// check for change to dn, and if so then set up newrdn and newSuperior variables
					if (!previousDN.toLowerCase().equals(sourceDN.toLowerCase())) { 
						try {
							ldapName = new javax.naming.ldap.LdapName(sourceDN)
						} catch (ex) {
							throw where() + " - " + resource.getString("LDAPSYNC.ERROR.PARSING.SOURCE.DN.TO.HANDLE.MODDN") + ": " + ex + " - dn: " + sourceDN
						}	
						rdns = ldapName.getRdns()
						newrdn = rdns.get(rdns.size()-1).toString()
						ldapName.remove(rdns.size()-1)
						newSuperior = ldapName.toString()
						logmsg("----->> " + resource.getString("LDAPSYNC.DETECTED.RENAME") + " newSuperior: " + newSuperior + "   newrdn: " + newrdn)
					}
				}	
			}	
		} 
	} 

	// if type is still unknown, try looking the entry up in the target using the adDn
	if ("unknown".equals(typeOfEntry) ||
		((filterOnGroups || filterOnAttributes) && !foundInTarget)) {

		// in case this is a modrdn or moddn, we have to look for the new DN in the source
		lookupDN = sourceDN
		sc = system.newSearchCriteria();

		if (targetIsTDS) {
			sc.addCriteria(auxLinkedDNAttribute, sc.EXACT, lookupDN.toLowerCase());
		} else {
			sourceAtt = work.getString("targetDn");
			if (sourceAtt !== null) {
				sourceAtt = cleanDN(sourceAtt).toLowerCase();
				work[auxLinkedDNAttribute] = sourceAtt;			
			} else {
				sourceAtt = work.getString("$dn").toLowerCase();
			}

			sc.addCriteria(targetLinkAttribute, sc.EXACT, sourceAtt);
		}	

		if (sc.getCriteria().size() > 0) {

			targetLDAP.setParam("ldapReturnAttributes", auxLinkedDNAttribute + "\n" + auxLinkedGUIDAttribute + "\nsn\ncn\nobjectClass\n"+containerRDNs+targetUserRDN);
			try {
/*				
				java.lang.System.out.println("--> W2T/Initialize Cycle - "
						+ " $dn: " + work.getString("$dn")
						+ " tdn: " + work.getString("targetDn")
						+ " adDn: " + work.getString(auxLinkedDNAttribute));

				java.lang.System.out.println("--> W2T/Initialize Cycle - lookup on delete for "
					+ sc.getCriteria()[0].name 
					+ " eq " 
					+ sc.getCriteria()[0].value);
*/
				sourceEntry = targetLDAP.findEntry(sc);
				if (sourceEntry == null) {
					if (targetLDAP.getFindEntryCount() > 1) {
						logmsg("WARN", "--> " +
									resource.getString("LDAPSYNC.MULTIPLE.ENTRIES.WERE.FOUND.IN.THE.TARGET") 
									+ "  " + auxLinkedDNAttribute
									+ " = " + lookupDN.toLowerCase())
						dupEntry = targetLDAP.getFirstFindEntry()
						do {
							logmsg("WARN", "      --> " + resource.getString("LDAPSYNC.DUPLICATE.ENTRY") + ": "
										+ dupEntry.getString("$dn"))
							dupEntry = targetLDAP.getNextFindEntry()
						} while (dupEntry != null)

						if (targetLDAP.getMaxDuplicateEntries() > targetLDAP.getFindEntryCount()) {
							logmsg("WARN", "..." + resource.getString("LDAPSYNC.MORE.ENTRIES.EXIST"))
						}
					}
				} else { // sourceEntry != null
					// handled further down when sourceEntry !== null
				}	
			} catch (ex) {
				sourceEntry = null
			}

			foundInTarget = (sourceEntry !== null);

			if (deBug) logmsg("-@@-->> target lookup for renamed/moved entry using " + auxLinkedDNAttribute + " = " + lookupDN +
					(sourceEntry == null ? " - failed" : " - success")
					+ "\n" + sourceEntry)
		}	
	}
}

// if we have a sourceEntry then try to determine type
if (sourceEntry == null) {
	sourceEntry = work // otherwise we only have the source data passed in
//	sourceEntry = system.newEntry();
} else {
	work[auxLinkedDNAttribute] = sourceEntry.getString(auxLinkedDNAttribute);
	work[auxLinkedGUIDAttribute] = sourceEntry.getString(auxLinkedGUIDAttribute);
	work.objectClass = sourceEntry.getString("objectClass");
	targetLDAPDN = sourceEntry.getString("$dn")
	if (rdnValue == null && !"???".equals(readRDN)) {
		rdnValue = getRDN(sourceEntry, readRDN);
	}
}

oc = work.objectClass;
typeOfEntry = entryType(oc);

// If identification fails, then skip this entry with an error message
//
if ("unknown".equals(typeOfEntry)) {
	logmsg("WARN",resource.getString("LDAPSYNC.UNABLE.TO.IDENTIFY.TYPE.OF.ENTRY") + ":\n" + jsonStr(work))
	addToStats(flowKey, "warn","warn");
	addToStats(flowKey, "unknown","skipped");
	system.skipEntry()
}
else
if (cloudSync) {
	useRDN = sourceRDNAtt
	readRDN = useRDN
} 
else
if ("person".equals(typeOfEntry)) {
	useRDN = targetUserRDN
	readRDN = sourceUserRDN
}
else
if ("group".equals(typeOfEntry)) {
	useRDN = "cn"
	readRDN = useRDN
}
else {	
	// if type is unknown then this caught below, else it's a container so use the source RDN
	useRDN = sourceRDNAtt
	readRDN = useRDN
}

if (rdnValue == null && readRDN.equalsIgnoreCase(sourceRDNAtt)) {
	rdnValue = sourceRDNValue
	encodeRDN = false // already encoded
}	

// Try to get tmhe RDN value - necessary for DN translation
if (rdnValue == null) {
	rdnValue = getRDN(sourceEntry, readRDN);
}	

if (rdnValue == null) {
	if ("person".equals(typeOfEntry)) {
		logmsg("ERROR",resource.getString("LDAPSYNC.CANNOT.FIND.RDN.ATTRIBUTE") + " (" + targetUserRDN + ") -> " + typeOfEntry + " entry: " + work.getString("$dn"))
		addToStats(flowKey, "error","error");
		addToStats(flowKey, typeOfEntry, "error")
		addToStats(flowKey, typeOfEntry, "skipped")
		system.exitFlow()
	} else {
		rdnValue = sourceRDNValue; // TODO should it be a call to getRDN()?
		encodeRDN = false // already encoded
	}	
}	

if (encodeRDN) {
	rdnValue = javax.naming.ldap.Rdn.escapeValue(cleanRDN(rdnValue))
}

work[readRDN] = rdnValue;
if (cn == null) {
	work["cn"] = sourceEntry["cn"];
}

// Increment the entry count and display message
callCount++;

if(changeDetection){
	logmsg("INFO","-> " + resource.getString("LDAPSYNC.PROCESSING") + " " + ((newrdn != null) ? "rename " : deltaOperationTag)
			+ " - " + typeOfEntry
			+ ((chglogMsg.length == 0) ? "" : " - " + chglogMsg)
		   	+ " - target dn: " + sourceDN);
} else {
	if((progressReport > 0) && (callCount % progressReport ) == 0){
		logmsg("INFO", resource.getString("LDAPSYNC.PROCESSING") + " " + typeOfEntry + " - " 
				+ resource.getString("LDAPSYNC.CURRENT.COUNT")+ ":" + callCount);
	}	
}

// Add to stats over entries processed
//
addToStats(flowKey,"total","processed")
if(typeOfEntry == "person" || typeOfEntry == "group"){
	addToStats(flowKey, typeOfEntry,"processed");
	opEntry["$typeOfEntry"] = typeOfEntry;
	work["$typeOfEntry"] = typeOfEntry;
} else{
	addToStats(flowKey, "container","processed");
	opEntry["$typeOfEntry"] = "container";
	work["$typeOfEntry"] = "container";
}

// the adDn may have been set during a target lookup above. If not, set it.
if (work[auxLinkedDNAttribute] === null) {
	work[auxLinkedDNAttribute] = cleanDN(work.getString("$dn").toLowerCase());
}	
work[auxLinkedGUIDSourceAttribute] = sourceGUID;

opEntry.setAttribute("$entry", prepareFindEntry(work, useRDN, rdnValue));

if (debugging) java.lang.System.out.println("W2T Init - op.type: " + opEntry.getString("$typeOfEntry") + " - " + opEntry.getString("$sourceDN"));

AttributeMapItem.Script:
if (targetLDAPDN !== null)
	return targetLDAPDN;
else
	return translateDN(sourceDN, useRDN, rdnValue, targetSuffixForUsers);

Hook.Script:
targetCtr = opEntry.getObject("$ctr");

if (targetCtr === null) {
	targetCtr = thisConnector.connector;
}

if (targetCtr instanceof com.ibm.di.connector.LDAPConnector) {
	targetCtr.setsubtreeDeleteSupported(true);
	targetIsLDAP = true;
}

targetLDAP = targetCtr;

work["$operation"] = "delete";
work["$conn"] = null;
thisConnector.connector.setParam("ldapReturnAttributes", "objectClass");
if (doTiming) timing("writetotarget - delete lookup");

addLinkedAttributes(work, conn, useRDN, rdnValue, changeDetType, newrdn, newSuperior, "person")

if ("true".equals(getProperty("password.enabled"))) {
	mappedPwd = conn.getObject("userPassword");
	pwd = generatePassword();
	conn.userPassword = pwd;
} else
if (conn.userPassword != null && conn.getString("userPassword") == null) {
	conn.removeAttribute("userPassword");
}

//java.lang.System.out.println("--> writing pwd: " + conn.getString("userPassword"));

if (auditEnabled || simulate) {
	simEntry = system.newEntry();
	simEntry.merge(conn);
	if (simulate) {
		simEntry = simplifyAttributes(simEntry);
	}	
}

if (deBug) logmsg("-@@@->> conn before add: " + jsonStr(conn))

work["$operation"] = "add";
work["$conn"] = conn;
if (doTiming) timing("writetotarget - adding")

addLinkedAttributes(work, conn, useRDN, rdnValue, changeDetType, newrdn, newSuperior, "person")
/*
if ("true".equals(getProperty("target.pwmap.auto"))) {
	mappedPwd = conn.getObject("userPassword");
	pwd = generatePassword();
	work.userPassword = pwd;
}
*/

if (auditEnabled || simulate) {
	simEntry = system.newEntry();
	simEntry.merge(conn);
	if (simulate) {
		simEntry = simplifyAttributes(simEntry);
	}	
}

if (targetIsLDAP) {
	conn.removeAttribute(useRDN); // do not write for modify operation
	conn.removeAttribute("objectClass");
	if (current !== null && current.getObject("ibm-pwdAccountLocked") === null) {
		conn.removeAttribute("ibm-pwdAccountLocked");
	}
}

change = true;

if (deBug) logmsg("-@@@->> conn before modify: " + jsonStr(conn))
//if (deBug) logmsg("--@-->> current before mod: " + jsonStr(current))

work["$operation"] = "modify"
work["$conn"] = conn;
if (doTiming) timing("writetotarget - modifying")

if (work["$writeStatus"] == null) {
	work["$writeStatus"] = "success";
}	

if (!passwordCaching || !isSync || !targetIsLDAP) {
	return;
}

// password cache reset if change detected
userPassword = work.getAttribute("$userPassword");
if (userPassword !== null) {
	pwdOp = userPassword.getOperation();
	if (deBug) { logmsg("--!!--> WriteToTarget (PwdCache) - (" + pwdOp + ") " + userPassword) }
	if (!"unchanged".equalsIgnoreCase(pwdOp)) {
		if (deBug) logmsg("--!!--> WriteToTarget (PwdCache) - resetting password for " + work.getString("$targetLDAPDN"))
		try {
			targetLDAP.removeAllAttributeValues(work.getString("$targetLDAPDN"), "userPassword");
			change = true;
		} catch (ex) {
			if (deBug) logmsg("--!!--> Exception: " + ex);
			if (ex.toString().toLowerCase().indexOf("nosuchattribute") < 0) {
				throw "AddModifyUser (PwdCache/Reset) - " + ex;
			}
		}	
	}
}

AttributeMapItem.Script:
if (targetLDAPDN !== null)
	return targetLDAPDN
else
	return translateDN(sourceDN, useRDN, rdnValue, targetSuffixForGroups)

Hook.Script:
work["$operation"] = "delete"
work["$conn"] = null;
thisConnector.connector.setParam("ldapReturnAttributes", "objectClass");
if (doTiming) timing("writetotarget - delete lookup");

Script.parameter:
targetMembers = system.newAttribute(targetGroupMemberAttribute);
sourceMemberAttributeDeleted = false;

if (simulate) {
	work.setAttribute("TargetUniqueMember", targetMembers);
	return;
}

// look for either 'member' or 'uniqueMember' attribute
sourceMemberAtt = "uniqueMember";
source = work.getAttribute(sourceMemberAtt);
if(source === null){
	sourceMemberAtt = "member";
	source = work.getAttribute(sourceMemberAtt);	
	if (source === null){
		source = system.newAttribute("member")
	}
}

sourceMemberAttributeDeleted = "delete".equals(source.getOperation());

if (!targetIsLDAP) {
	work.setAttribute("TargetUniqueMember", source);
	return;
}

targetMembers.setOperation(source.getOperation());

if (targetLDAP == null) {
	for (i = source.size(); i--;) {
		thisMember = source.getValue(i);
		if (thisMember !== null && thisMember.trim().length > 0) {
			targetMembers.addValue(source.getValue(i));
			valOp = source.getValueOperation(i);
			if (valOp == null || valOp.trim().length == 0) {
				valOp = "add"
			}
			targetMembers.setValueOperation(i, valOp);
		}	
	}	
} else {	
	badMembers = "";
	targetLDAP.setParam("ldapReturnAttributes",targetUserRDN+"\nsn\ncn\nobjectClass\n" + auxLinkedGUIDAttribute + "\n" + auxLinkedDNAttribute);
	for(i=0; i < source.size(); i++){
		thisMember = source.getValue(i).toLowerCase();
		memberDN = null;
		if (thisMember.trim().length == 0) {
			continue;
		}

		oldDN = cleanDN(thisMember);

		sc = system.newSearchCriteria();
		sc.addCriteria(auxLinkedDNAttribute,sc.EXACT,oldDN)
		try {
			mem = targetLDAP.findEntry(sc);
		} catch (ex) {
			mem = null
		}

		if (mem !== null) {
			memberDN = mem.getString("$dn");
		} else
		if (mem === null
			&& targetLDAP.getFindEntryCount() == 0 
			&& (result = checkScope(thisMember, sourceLDAP, changeDetType)).inScope) {
			mem = result.entryRead;
			if (mem != null) {

				memberType = result.typeOfEntry;

				if ("person".equals(memberType)) {
					memuseRDN = targetUserRDN;
					memreadRDN = sourceUserRDN;
					memsuffix = targetSuffixForUsers;
				}
				else
				if ("group".equals(memberType)) {
					memuseRDN = "cn"
					memreadRDN = useRDN
					memsuffix = targetSuffixForGroups;
				}
				else {
					// skip this entry
					if (deBug) logmsg("ERROR", "Could not identify member type: " + thisMember);
					continue;
				}

				try {
					memrdnValue = mem.getString(memreadRDN);
					if (memrdnValue === null) {
						if (deBug) logmsg("ERROR", "Error no RDN attribute for member: " + thisMember + " (" + memreadRDN + ")");
					} else {	
						memrdnValue = javax.naming.ldap.Rdn.escapeValue(cleanRDN(memrdnValue));
					}	
				} catch (ex) {
					if (deBug) logmsg("ERROR", "Error cleaning member RDN: " + thisMember + "   rdnValue: " + memrdnValue + " (" + memreadRDN + ")");
					memrdnValue = null;
				}	

				if (memrdnValue !== null) {
					try {
						memberDN = translateDN(oldDN, memuseRDN, memrdnValue, memsuffix, null, null);
					} catch (ex) {
						// could not identify this member
						if (deBug) logmsg("ERROR", "--&&--> Error translating member dn: " + oldDN);
						mem = null;
						memberDN = null;
					}	

				}

			}
		}	

		if(mem === null){
			if (targetLDAP.getFindEntryCount() > 1) {
				badMembers += "--> " +
							resource.getString("LDAPSYNC.SKIPPING.MEMBER.BECAUSE.MULTIPLE.ENTRIES.WERE.FOUND.IN.THE.TARGET") 
							+  auxLinkedDNAttribute + " = " + oldDN + "\n"
				mem = targetLDAP.getFirstFindEntry()
				do {
					badMembers += "      " + resource.getString("LDAPSYNC.DUPLICATE.ENTRY") + ": "
								+ mem.getString("$dn") + "\n"
					mem = targetLDAP.getNextFindEntry()
				} while (mem != null)

				if (targetLDAP.getMaxDuplicateEntries() > targetLDAP.getFindEntryCount()) {
					badMembers += "      ..." + resource.getString("LDAPSYNC.MORE.ENTRIES.EXIST") + "\n"
				}
			} else {	
				badMembers += "--> " +
							resource.getString("LDAPSYNC.SKIPPING.MEMBER.BECAUSE.NO.ENTRY.WAS.FOUND.IN.THE.TARGET") 
							+ auxLinkedDNAttribute + " = " + oldDN + "\n"
			}

			addToStats(flowKey, "warn","warn")
			continue;
		}

		if (memberDN !== null && memberDN.trim().length > 0) {
			targetMembers.addValue(memberDN);
			if (sourceMemberAttributeDeleted) {
				valOp = "delete";
			} else {
				valOp = source.getValueOperation(i);
				if (valOp == null || valOp.trim().length == 0) {
					valOp = "add";
				}
			}	
			targetMembers.setValueOperation(targetMembers.size()-1, valOp);
		}	
	}

	if (badMembers.length != 0) {
		logmsg("WARN",resource.getString("LDAPSYNC.THE.FOLLOWING.MEMBERS.WERE.NOT.ADDED.FROM.SOURCE.GROUP") 
					+ ": "+work.getString("$dn")+"\n"+badMembers);

		addToStats(flowKey, "missing","missing")	
		// if old file found, rename to GroupMembersLost<timestamp of file>.log

		logFile = openOutputFile(logFileFullname);
		logFile.newLine();
		logFile.write(system.formatDate(new java.util.Date(), "yyyy-MM-dd HH:mm:ss") 
						+ "  *** " + resource.getString("LDAPSYNC.CANNOT.FIND.THESE.MEMBERS.OF.THE.GROUP") + " "
						+ work.getString("$dn"));
		logFile.newLine();
		parts = system.splitString(badMembers,"\n")
		for (p in parts) {
			logFile.write(p);
			logFile.newLine();
		}	
		logFile.close();
	}	
}

if (sourceMemberAttributeDeleted) {
	if (!targetMembers.hasValue(dummyMember)) {
		targetMembers.addValue(dummyMember);
		targetMembers.setValueOperation(targetMembers.size()-1, "add");
	}	
}

work.setAttribute("targetUniqueMember", targetMembers);

