for (cnt = 0; cnt < al.length; cnt++) {
	try {
		al[cnt].join()
	} catch (ex) {
		setException(ex, "fatal")
	}	
}

if (al.length == 1) {
	ex = getException("fatal")

	if (ex == null) {
		ex = getException("error")
	}

	if (ex != null) {
		task.getStats().exception(new java.lang.Exception(ex))
//		throw ex
	}
}

try {
	dn = work.getString("$dn");

	if (dn === null) {
		logmsg("ERROR", where() + " - " + resource.getString("LDAPSYNC.NO.DN.ATTRIBUTE.FOUND.IN.ENTRY.SKIPPING"));
		addToStats(flowKey, "error", "error");
		system.continueLoop();
	}

	work["$dn"] = cleanDN(dn);
} catch (ex) {
	logmsg("ERROR", where() + " - " + resource.getString("LDAPSYNC.ERROR.PARSING.SOURCE.DN") + ": " + dn + " - " + ex);
	logmsg("WARN", where() + " - " + resource.getString("LDAPSYNC.SKIPPING"));
	addToStats(flowKey, "error", "error");
	system.continueLoop();
}

