	targetTCB.setAttribute("$hooksManager", task.getTCB().getAttribute("$hooksManager"));
//	targetTCB.setAttribute("$monitors", task.getTCB().getAttribute("$monitors"));
	targetTCB.setAttribute("$logFiles", task.getTCB().getAttribute("$logFiles"));
	targetTCB.setAttribute("$logf", task.getTCB().getAttribute("$logf"));
	targetTCB.setAttribute("$errorf", task.getTCB().getAttribute("$errorf"));
	targetTCB.setAttribute("$retryList", task.getTCB().getAttribute("$retryList"));

