}	

function setException(ex, type) {
	type = type.toLowerCase()

	if (lastException == null) {
		java.lang.System.out.println(where() + " - setException() - ex: " + ex + "   type: " + type + "  *** NO lastException set")
		return
	}

	ex = new java.lang.Exception(ex)

	lastException.put("latest", ex)
	lastException.put(rj(new java.util.Date().getTime(), 15), ex)

	if (getException(type) == null) {
		lastException.put(type, ex)
	}	
}

function getException(type) {
	if (lastException == null) {
		lastException = getLastException()
	}

	if (type == "first" || type == "root") {
		var keys = lastException.keySet().toArray()
		java.util.Arrays.sort(keys)
		return lastException.get(keys[0])	
	} else {
		return lastException.get(type)
	}	
}

function getLastException() {
	if (lastException == null) {
		lastException = alTCB.getObject("$lastException")
	}

	return lastException
}

