function getALName(pname, defVal) {
	if (typeof(defVal) == "undefined") {
		defVal = null
	}
	var ALname = getProperty(pname, null)

	if (ALname == null || ALname.trim().length == 0) {
		return defVal
	}

	var configName = getProperty("source.config.name", null)
	if (configName != null) {
		p = ALname.indexOf(":/")
		if (p < 0) {
			ALname = configName + ":/AssemblyLines/" + ALname
		}
	}

	if (!CIsetup(ALname)) {
		return null
	}			

	return ALname
}


