function formReport(formName) {
	var rep = new java.lang.StringBuffer();
	var connCfg = main.getMetamergeConfig().lookup("LDAPSync:/Connectors/" + formName);
	if (connCfg === null) {
		if (formName.equalsIgnoreCase("FlowSettings")) {
			connCfg = main.getMetamergeConfig().lookup("LDAPSync:/Connectors/Target_TDS");
		}

		if (connCfg === null) {	
			return resource.getString("LDAPSYNC.TARGET.FLOW.FORM.IS.MISSING") + ": " + formName;
		}	
	}
	var ciCfg = connCfg.getConnectionConfig()
	var title = resource.getString("LDAPSYNC.SOURCE.ENDPOINT")
	if (formName.equalsIgnoreCase("FlowSettings")) {
		title = resource.getString("LDAPSYNC.FLOW.SETTINGS")
	}

	rep.append(title + ":\n")

	var params = opEntry.getAttributeNames()
	java.util.Arrays.sort(params)
	var pname
	var pvalue
	var p
	var paramParts

	col1 = 0
	for (var thisParam in params) {
		p = thisParam.indexOf(".")
		pname = thisParam.substring(p+1)
		paramParts = system.splitString(thisParam, ".")
		if (ciCfg.getParameter(pname) != null && !pname.startsWith("stat") && paramParts.length > 2) {
			var newlen = resource.getString(thisParam).length + 1
			if (newlen > col1) {
				col1 = newlen
				col2 = pname.length + 1
			}
		}	
	}

	for (var thisParam in params) {
		p = thisParam.indexOf(".")
		pname = thisParam.substring(p+1)
		paramParts = system.splitString(thisParam, ".")
		if (ciCfg.getParameter(pname) != null && pname.indexOf(".stat") < 0 && paramParts.length > 2) {
			if (pname.toLowerCase().indexOf(".password") > 0) {
				pvalue = " --- "
			} else {
				pvalue = opEntry[thisParam]
			}	
			addLine(rep, "| " + lj(resource.getString(thisParam),col1)+ " | " + lj(pname,col2,"...") + " | " + (pvalue == null ? "* null *" : String(pvalue).trim()))
		}	
	}

	return rep.toString()
}

function ConnectorReport(ctrName) {
	var ctr = system.getConnector(ctrName)
	var nameLC = ctrName.toLowerCase()
	if (ctr == null) {
		msg = resource.getString("LDAPSYNC.PROPERTIES.IN.ERROR.CANNOT.CONFIGURE.CONNECTOR")
		logmsg("ERROR", msg + ": " + ctrName)
		return msg + "\n"
	}

	var strBuf = new java.lang.StringBuffer() 	// accumulate message
	var conCfg = ctr.getConfiguration()			// get Connector config
	var ciCfg = conCfg.getConnectionConfig()	// get Connector Interface config (e.g. ldap)
	var ciClass = ciCfg.getJavaClass()

	if (ciClass.indexOf("LDAPConnector") >= 0) {
		return LDAPReport(ctrName)
	} else {
		return "* Nothing *\n"
	}
}

function LDAPReport(ctrName) {
	var ctr = system.getConnector(ctrName)
	var nameLC = ctrName.toLowerCase()
	if (ctr == null) {
		msg = resource.getString("LDAPSYNC.PROPERTIES.IN.ERROR.CANNOT.CONFIGURE.CONNECTOR")
		logmsg("ERROR", msg + ": " + ctrName)
		return msg + "\n"
	}

	var strBuf = new java.lang.StringBuffer() 	// accumulate message
	var conCfg = ctr.getConfiguration()			// get Connector config
	var ciCfg = conCfg.getConnectionConfig()	// get Connector Interface config (e.g. ldap)
	var ciClass = ciCfg.getJavaClass()
	var ciFormCfg = main.getMetamergeConfig().lookup("system:/Forms/" + ciClass)
	var ciMMCfg = ciCfg.getMetamergeConfig()
	var plabel

	var params = ciCfg.getKeys(ciCfg.ONE_LEVEL).toArray()
	java.util.Arrays.sort(params)
	var destSource = (nameLC.indexOf("source") >= 0 || nameLC.indexOf("change") >= 0)
	var destMsg = (destSource ? "Source" : "Target")
	var changeDet = (nameLC.indexOf("change") >= 0)
	var changeDetMsg = ""
	if (changeDet) {
		changeDetMsg = "(Change Detection)"
	}

	addLine(strBuf, "-->> " + destMsg + " " + resource.getString("LDAPSYNC.ENDPOINT") + " " + changeDetMsg)
	for (var pndx = 0; pndx < params.length; pndx++) {
		thisParam = params[pndx]
		plabel = thisParam
		var paramParts = system.splitString(thisParam, ".");
		if (thisParam != "inheritFrom" && thisParam != "debug" && !thisParam.startsWith("$form") && paramParts.length > 2) {
			var paramLC = String(thisParam).toLowerCase()
			var pvalue = ciCfg.getParameter(thisParam)
			var pread = thisParam
			var psource = ciCfg.getParameterPropertySource(thisParam)
			var psourceEval = null

			try {
				psourceEval = (psource != null) ? evaluate(psource) : null

				if (psourceEval != null)
					pread = String(propertyRead)
				else {
					var p = psource.indexOf("pname")
					var foundPname = "* not set: " + thisParam + " *"
					if (p >= 0) {
						var p2 = psource.indexOf("\"", p)
						if (p2 >= 0) {
							p = psource.indexOf("\"", p2+1)
							if (p > p2) {
								foundPname = psource.substring(p2+1,p-1)
							}
						}
					}
					pread = foundPname
				}	

				var formItem = ciFormCfg.getFormItem(thisParam)
				if (formItem != null) {
/*				
					plabel = formItem.getLabel()
					if (plabel == null || plabel.length == 0) {
						plabel = thisParam
					}	
*/
					if (formItem.getDontProtect() || paramLC.indexOf("password") >= 0 || paramLC.indexOf("user") >= 0) {
						pvalue = "---"
					}	
				}	
			} catch (ex) {
				psourceEval = "** error evaluating property: " + thisParam + " for " + ctr.getName() + " **"
			}	

//			if (!changeDet || (paramLC.indexOf("url") < 0 && paramLC.indexOf("user") < 0 && paramLC.indexOf("password") < 0 && paramLC.indexOf("ldap.searchbase") < 0))
			if (!changeDet || (paramLC.indexOf("url") < 0 && paramLC.indexOf("user") < 0 && paramLC.indexOf("password") < 0 && paramLC.indexOf("ldap.searchbase") < 0))
				addLine(strBuf, "| " + lj(plabel,col1)+ " | " + lj(propertyRead,col2,"...") + " | " + (pvalue == null ? "* null *" : String(pvalue).trim()))
		}	
	}

	return strBuf.toString()
}


function MapFileStatus(objType) {
	var mapFilePropName = "target." + objType + ".mapFile"
	var mapFile = getProperty(mapFilePropName)
	if (mapFile == null || mapFile.length == 0) {
		propertyRead = "<" + resource.getString("LDAPSYNC.PROPERTY.NOT.SPECIFIED") + ">"
		mapFile = objType + ".map"
	}	
	if (mapFile.indexOf("/") < 0 && mapFile.indexOf("\\") < 0)
		mapFile = configDirectory + "/" + mapFile

	var file = new java.io.File(mapFile)
	var msg = ""
	if (file.exists()) {
		msg = resource.getString("LDAPSYNC.OK")
	} else {	
		msg = resource.getString("LDAPSYNC.NOT.FOUND.OR.INACCESSIBLE")
	}

	return "| " + lj(objType ,col1)+ " | " + lj(propertyRead,col2) + " | " + msg + " > " + file.getAbsolutePath()
}

function MapFilesReport() {
	var strBuf = new java.lang.StringBuffer()

	addLine(strBuf, "-->> " + resource.getString("LDAPSYNC.MAPPING.FILES"))
	addLine(strBuf, MapFileStatus("person"))
	addLine(strBuf, MapFileStatus("group"))
	itr = containerOC.keySet().iterator()
	while (itr.hasNext()) {
		addLine(strBuf, MapFileStatus(itr.next()))
	}

	return strBuf.toString()
}

function BehaviorReport() {
	var strBuf = new java.lang.StringBuffer()
	addLine(strBuf, "-->> " + resource.getString("LDAPSYNC.BEHAVIOR"))
	var sourceProps = "simulate,source.handlePersonObjects,source.handleGroupObjects,source.containersToMigrate,source.containersToSkip,source.userRDN,source.userObjectClass,source.groupObjectClass,source.container.objectClasses"
	var targetProps = "target.userRDN,target.userObjectClass,target.groupObjectClass,target.isTDS"
	var flattenProps = "target.suffixForUsers,target.suffixForGroups"
	var changeDetType = getProperty("source.changeDetectionType","delta").toLowerCase()
	var flatten = !("true".equalsIgnoreCase(getProperty("mirroring.enabled")) && "true".equalsIgnoreCase(getProperty("global.preserveSourceContainers")))
	var flattenRead = propertyRead

	if (flatten) {
		if (handleType.person == true) {
			sourceProps += ",target.suffixForUsers"
		}	
		if (handleType.group == true) {
			sourceProps += ",target.suffixForGroups"
		}	
	}

	addLine(strBuf, "| " + lj(resource.getString("LDAPSYNC.MIRRORING.HIERARCHY") ,col1)+ " | " + lj(flattenRead,col2) + " | " + String(flatten).trim())

	var useProps = sourceProps + "," + targetProps
	if (!flatten)
		useProps = flattenProps + "," + useProps
	useProps = system.splitString(useProps,",")

	for (var p in useProps) {
		pval = getProperty(p)
		if (pval != null)
			pval = pval.trim()
		else
			pval = "<" + resource.getString("LDAPSYNC.NOT.SET") + ">"
		addLine(strBuf, "| " + lj(p ,col1)+ " | " + lj(propertyRead,col2) + " | " + pval.trim())
	}

	return strBuf.toString()
}

