function propertyReport(propType) {
	var attNames = opEntry.getAttributeNames();
	var paramParts;
	var strBuf = new java.lang.StringBuffer();
	var pval;
	var pvalParts;
	var firstval;
	var i
	java.util.Arrays.sort(attNames);
	for (var pname in attNames) {
		paramParts = system.splitString(pname, ".");
		if (paramParts.length > 2 && pname.toLowerCase().indexOf(propType) > 0) {

			// obfuscate password properties
			if (pname.toLowerCase().indexOf("password") >= 0) {
				pval = "*********";
			} else {	
				pval = getProperty(pname) + "";
			}	

			pvalParts = system.splitString(pval, "\n")
			if (pvalParts === null || pvalParts.length == 0) {
				firstval = pval;
			} else {
				firstval = pvalParts[0];
			}
			addLine(strBuf, "| " + lj(pname ,col1)+ " | " + firstval.trim());
			if (pvalParts[0] != "undefined" && pvalParts.length > 1) {
				for (i = 1; i < pvalParts.length; i++) {
					addLine(strBuf, "| " + lj("" ,col1)+ " | " + pvalParts[i].trim());
				}	
			}	
		}	
	}	

	return strBuf.toString();
}	

function flowKeyMsg() {
	if (typeof(flowKey) == "undefined")
		return "> "

	if ("S".equals(flowKey) || "M".equals(flowKey))
		return ""
	else {
		return "["+ flowKey + "] "
	}
}

function getRDN(entry, rdnSpec) {
	if (!entry || !rdnSpec) { throw "arguments for getRDN must be 'entry' and 'rdnSpec'"; }

	var attValue = entry.getString(rdnSpec);
	if (attValue != null) {
		return attValue;
	}	

	var saveWork = work;
	var rdnValue;

	try {
		work = entry;
		eval("rdnValue = " + rdnSpec);
		work = saveWork;
		return rdnValue;
	} catch (ex) {	
//		if (deBug) logmsg("ERROR", "Error evaluating RDN assignment script: " + rdnSpec + "    - " + ex);
		work = saveWork;
	}	
}		

function evaluate(e, expr) {
	if (typeof(expr) == "undefined") {
		expr = e
		e = work
	}
	var expression = system.getTDIExpression(expr);

	var useE = system.newEntry()

	if (typeof(e) != "undefined" && e != null) {
		useE.merge(e)
	}	

	var map = new java.util.concurrent.ConcurrentHashMap()
	map.put("mc", main.getMetamergeConfig());
	map.put("task", task);
	map.put("main", main);
	map.put("user", useE);
	map.put("data", useE);
	map.put("work", useE);
	map.put("entry", useE);
	map.put("target", useE);
	data = useE;

	return expression.substitute(map);
}



// These next functions are for reporting 
//
function prepareReport() {
	if ("true".equals(getProperty("simulate")))
		logmsg("**** " + resource.getString("LDAPSYNC.SIMULATION.ONLY.NO.DATA.WILL.BE.CHANGED.IN.THE.TARGET") + " ****")

	syncReport = alTCB.getObject("$syncReport")
	if (syncReport == null) {
		syncReport = new java.util.concurrent.ConcurrentHashMap();
		alTCB["$syncReport"] = syncReport
	}	

	return syncReport
}

function logReport(flowKey) {
	if (typeof(syncReport) == "undefined" || syncReport == null) { return; } 

	if ("true".equals(getProperty("simulate")))
		logmsg("**** " + resource.getString("LDAPSYNC.SIMULATION.ONLY.NO.DATA.HAS.BEEN.CHANGED.IN.THE.TARGET") + " ****")

	logmsg("\n" + generateReport(flowKey))
}

function flowLabel(flowKey) {
	if ("M".equals(flowKey) || flowKey.trim().length == 0)
		return "migration"
	else
	if ("S".equals(flowKey))
		return "synchronization"
	else
		return flowKey
}

function stat(msg, val) {
	if (val <= 0)
		return ""
	return "  " + msg + ": " + val
}

function generateReport(flowKey){
	var errors = 0;
	var warnings = 0;
	var report = new java.lang.StringBuffer("-o@o-o@o-o@o-o@o-o@o-o@o-o@o-\n")
	if (cloudSync) {
		report.append("====== " + resource.getString("CLOUDSYNC.SUMMARY") + " ======");
	} else {	
		report.append("====== " + resource.getString("LDAPSYNC.SUMMARY.FOR.FLOW") + ": " + flowLabel(flowKey) + " ======");
	}	
	report.append("\n")

	report.append(lj("- Person",12) + " " + resource.getString("LDAPSYNC.TOTAL") + ": " + getStats(flowKey, "person", "processed")
				+ stat(resource.getString("LDAPSYNC.ADD"), getStats(flowKey, "person", "add"))
				+ stat(resource.getString("LDAPSYNC.MOD"), getStats(flowKey, "person", "modify"))
				+ stat(resource.getString("LDAPSYNC.DELETE"), getStats(flowKey, "person", "delete"))
				+ stat(resource.getString("LDAPSYNC.UNCHANGED"), getStats(flowKey, "person", "unchanged"))
				+ stat(resource.getString("LDAPSYNC.SKIP"), getStats(flowKey, "person", "skipped"))
				+ stat(resource.getString("LDAPSYNC.WARNING"), getStats(flowKey, "person", "warn"))
				+ stat(resource.getString("LDAPSYNC.ERROR"), getStats(flowKey, "person", "error"))
				);
	report.append("\n")

	if (handleType.group && !cloudSync) {
		report.append(lj("- Group",12) + " " + resource.getString("LDAPSYNC.TOTAL") + ": " + getStats(flowKey, "group", "processed")
					+ stat(resource.getString("LDAPSYNC.ADD"), getStats(flowKey, "group", "add"))
					+ stat(resource.getString("LDAPSYNC.MOD"), getStats(flowKey, "group", "modify"))
					+ stat(resource.getString("LDAPSYNC.DELETE"), getStats(flowKey, "group", "delete"))
					+ stat(resource.getString("LDAPSYNC.UNCHANGED"), getStats(flowKey, "group", "unchanged"))
					+ stat(resource.getString("LDAPSYNC.SKIP"), getStats(flowKey, "group", "skipped"))
					+ stat(resource.getString("LDAPSYNC.WARNING"), getStats(flowKey, "group", "warn"))
					+ stat(resource.getString("LDAPSYNC.ERROR"), getStats(flowKey, "group", "error"))
					);
		report.append("\n")
	}

	if (handleType.container && !cloudSync) {	
		report.append(lj("- Container",12) + " " + resource.getString("LDAPSYNC.TOTAL") + ": " + getStats(flowKey,"container", "processed")
					+ stat(resource.getString("LDAPSYNC.ADD"), getStats(flowKey, "container", "add"))
					+ stat(resource.getString("LDAPSYNC.MOD"), getStats(flowKey, "container", "modify"))
					+ stat(resource.getString("LDAPSYNC.DELETE"), getStats(flowKey, "container", "delete"))
					+ stat(resource.getString("LDAPSYNC.UNCHANGED"), getStats(flowKey, "container", "unchanged"))
					+ stat(resource.getString("LDAPSYNC.SKIP"), getStats(flowKey, "container", "skipped"))
					+ stat(resource.getString("LDAPSYNC.WARNING"), getStats(flowKey, "container", "warn"))
					+ stat(resource.getString("LDAPSYNC.ERROR"), getStats(flowKey, "container", "error"))
					);
		report.append("\n");
	}

	report.append("--------------\n")

	report.append(resource.getString("LDAPSYNC.ERRORS") + ": " + getStats(flowKey,"error", "error"))
	report.append("\n")
	report.append(resource.getString("LDAPSYNC.WARNINGS") + ": " + getStats(flowKey,"warn", "warn"))
	report.append("\n")
	report.append(resource.getString("LDAPSYNC.SKIP") + ": " + getStats(flowKey,"skip", "skip"))
	report.append("\n")

	if (getStats(flowKey,"missing","missing") > 0) {
		report.append("\n")
		report.append(resource.getString("LDAPSYNC.ONE.OR.MORE.GROUP.MEMBERS.WERE.NOT.MIGRATED"))
