// Helper function for updateStats() below
function updateWorkFromTargetTCB(targetTCB, attname) {
	if (targetTCB[attname] !== null) {
		if ("$error".equalsIgnoreCase(attname)) {
			var attval = targetTCB[attname].toString();
			if (attval.indexOf("CTGDIS483E") >= 0) {
				return;
			}	
		}	
		work[attname] = targetTCB[attname]
	}		
}	

// This function checks the possible return status for a called WriteToTarget AL
// These values are in the TCB
function updateStatusFromTCB(targetTCB, isChange) {
	if (typeof(isChange) == "undefined") {
		isChange = true;
	}

	if (targetTCB !== null) {
		updateWorkFromTargetTCB(targetTCB, "$writeStatus");
		updateWorkFromTargetTCB(targetTCB, "$status");
		updateWorkFromTargetTCB(targetTCB, "$change");
		updateWorkFromTargetTCB(targetTCB, "$error");
		updateWorkFromTargetTCB(targetTCB, "$stopFlow");

		if (work["$change"] !== null) {
			isChange = isChange && 
						"true".equalsIgnoreCase(work.getString("$change")) &&
						"success".equalsIgnoreCase(work.getString("$writeStatus"));
		}	
	} else {
		work["$writeStatus"] = "success"
	}

	change = isChange;
}	

function addToStats(flowKey, entryType, operation, changelog, displayDN){
	if (typeof(changelog) === "undefined" || changelog === null) { changelog = false; } 
	if (typeof(operation) === "undefined" || operation === null) { operation = "?" } 
	if (typeof(entryType) === "undefined" || entryType === null) { entryType = "person" } 

	entryType = entryType.toLowerCase()
	operation = operation.toLowerCase()

	var useType = entryType
	var tChar = useType.substring(0, 1)
	if (!(tChar.equals("p") || // person
		  tChar.equals("g") || // group
		  tChar.equals("w") || // warning
		  tChar.equals("e") || // error
		  tChar.equals("s") || // skipping
		  tChar.equals("m") || // missing
		  tChar.equals("i") || // ignored
		  tChar.equals("t"))) { // total
		useType = "container"
		tChar = "c"
	}
/*	
try {	
	if (tChar == "e") java.lang.System.out.println("Adding error from " + task.getShortName() + " - " + thisConnector.getName());
} catch (ex) {
	if (tChar == "e") java.lang.System.out.println("Adding error from " + task.getShortName());
}		
*/		
	if ((typeof(displayDN) == "undefined" || displayDN === null) && typeof(work) !== "undefined" && work !== null)
		displayDN = work.getString("$dn")
	if (displayDN != null && displayDN.length > 0)
		displayDN = ": " + displayDN


	if(typeof syncReport === "undefined" || syncReport === null){
		syncReport = alTCB.getObject("$syncReport")
		if (syncReport == null) {
			prepareReport()
		}
	}

	var stats = syncReport.get(flowKey)
	if (stats == null) {
		stats = new java.util.concurrent.ConcurrentHashMap()
		syncReport.put(flowKey, stats)
	}	
	var key = tChar + operation.substring(0,1).toLowerCase();
	var num = stats.get(key);
	if(num == null){
		num = 1;
	}else{
		num++;
	}

	if(changelog) {
		if ("unchanged".equals(operation)) {
			logmsg("INFO"," => " + resource.getString("LDAPSYNC.UNCHANGED") + " "+ entryType + " " + displayDN)
		} else
		if (!"generic".equals(operation)) {
			logmsg("INFO"," => " + resource.getString("LDAPSYNC.SUCCESSFUL") + " "+operation + " " + entryType + " " + displayDN)
		} else
		if ("s".equals(operation.substring(0,1))) {
			logmsg("INFO"," => " + resource.getString("LDAPSYNC.SKIPPING") + " " + entryType + " " + displayDN)
		}

		if (debugging) logmsg("-------------");
	}
	stats.put(key,num);

	// for the sync activity log
	syncReport.put(flowKey + "_lastOperation", entryType + "/" + operation)

	updateProgressReport(flowKey, entryType, false)
}

function getStats(flowKey, entryType, operation){
	var key;
	var num = 0;
	var types = ["p", "g", "c"];
	if(typeof syncReport === "undefined" || syncReport === null || syncReport.get(flowKey) === null) { return 0; }

	var stats = syncReport.get(flowKey)

	key = entryType.substring(0,1).toLowerCase() + operation.substring(0,1).toLowerCase();
	val = stats.get(key);
	if (val != null && val > 0) {
		num = val;
	}	

	if (entryType == operation) { // "error" or "warning" totals
		for (var i = 0; i < types.length; i++) {
			key = types[i].toLowerCase() + operation.substring(0,1).toLowerCase();
			val = stats.get(key);
			if (val != null) {
				num += val;
			}	
		}	
	}

	return num;
}

function entryType(oc){
	var val

	if (typeof(oc) == "undefined" || oc == null) {
		return "unknown"
	}

	if (tuocList == null) {
		tuocList = system.splitString(targetUserObjectClass.toLowerCase(),",")
	}

	if (typeof(sourceUserObjectClass) == "undefined" || typeof(sourceGroupObjectClass) == "undefined")
		throw where() + " - utils::entryType() - " + resource.getString("LDAPSYNC.SOURCEUSEROBJECTCLASS.ANDOR.SOURCEGROUPOBJECTCLASS.IS.UNDEFINED")

	for(var i = oc.size()-1; i >= 0; i--){
		val = oc.getValue(i).trim().toLowerCase();
		if(val.equalsIgnoreCase(sourceUserObjectClass))
			return "person";

		for (var j = (tuocList.length-1); j >= 0; j--) {
			if (val.equalsIgnoreCase(tuocList[j]) && !"top".equals(tuocList[j])){
				return "person"
			}
		} 
		if(val.equalsIgnoreCase(sourceGroupObjectClass) 
			|| val.equalsIgnoreCase(targetGroupObjectClass)) {
			return "group";
		}
	}
	for(var i = oc.size()-1;i>=0;i--){
		val = oc.getValue(i).trim().toLowerCase();
		if(! "top".equalsIgnoreCase(val) && val.indexOf("change") < 0 && ! auxLinkedEntryClassName.equals(val))
			return oc.getValue(i).toLowerCase();
	}

	return "unknown"
}

var logf = null
var errorf = null
function prepareLog(filename) {
	var logfile;
	var filepath;

	if (!utilsReady) {
		return null;
	}

	filepath = logDirectory + "/" + filename + ".temp";

	logfilepath = filepath
	try {
		logfile = openOutputFile(logfilepath)
	} catch (ex) {
		throw where() + " **" + resource.getString("LDAPSYNC.ERROR.CREATING.LOG.FILE") + ": " + logfilepath + " - " + ex
	}	
	var lf = new java.io.File(logfilepath)
	if (!lf.exists()) {
		throw where() + " **" + resource.getString("LDAPSYNC.ERROR.CREATING.LOG.FILE") + ": " + logfilepath + " - " 
			+ resource.getString("LDAPSYNC.UNABLE.TO.CREATE.FILE")
	}
	logFiles.setAttribute(logfilepath, logfile)
	return logfile
}

function rollLogs() {
	if (typeof(logFiles) == "undefined") {
		return
	} else
	if (logsRolled) {
		return
	}

	logsRolled = true

	var totals = flowTotals()	
	rollExistingFiles(totals)

	var logFilenames = logFiles.getAttributeNames();
	var errorLogName = ""; // roll error log last - just in case
	for (var lfName in logFilenames) {
		if (lfName.indexOf("_Errors") > 0) {
			errorLogName = lfName;
		} else {	
			rollFile(lfName, totals);
		}	
	}

	if (errorLogName !== "") {
		rollFile(errorLogName, totals);
	}	
}

function rollExistingFiles(totals) {
	if (totals == 0 || simulate) {
		return;
	}	

	var logdir = new java.io.File(logDirectory)
	var list = logdir.list()
	var prefix = flowKey + "_"
	var numberedFiles = new java.util.concurrent.ConcurrentHashMap()
	var lastlog = new java.util.ArrayList()
	var filename
	var filenumStr = ""
	var filenum = -1
	var firstpart = ""
	var filepath

	for (var i = list.length-1; i >= 0; i--) {
		filename = list[i]
		filepath = logDirectory + "/" + filename
		if (filename.startsWith(prefix) 
			&& filename.indexOf("_server.log") < 0 
			&& filename.indexOf("_audit") < 0 
			&& filename.indexOf("_simulate.log") < 0 
			&& filename.indexOf("_Activity.log") < 0) {
			var p = filename.lastIndexOf(".")

			// first close file if open
			closeFile(filename)

			if (p > 0) {
				filenumStr = filename.substring(p+1).trim()
				if (system.isValidInt(filenumStr)) {
					filenum = system.toInt(filenumStr)
					if (filenum >= maxLog) {
						task.logmsg("===> Deleting " + filename)
						if (!system.deleteFile(filepath)) {
							logmsg("ERROR", resource.getString("LDAPSYNC.ERROR.DELETING.OLD.LOG") + ": " + filename + " - " + system.lastError)
						}
					} else {
						numberedFiles.put(rj(filenum,5) + "_" + filepath, filenum)
					}	
				} 
				else 
				if (filenumStr.equals("log") || filenumStr.equals("ldif")){
					lastlog.add(filepath)
				}
			}	
		}	
	}

	var keys = numberedFiles.keySet().toArray()
	java.util.Arrays.sort(keys)
	for (var i = keys.length-1; i >= 0; i--) {
		var key = keys[i]
		filenum = numberedFiles.get(key)
		filename = key.substring(key.indexOf("_")+1)
		p = filename.lastIndexOf(".")
		firstpart = filename.substring(0, p)
		task.logmsg("===> Rolling " + filename + " to " + firstpart + "." + (filenum+1))
		if (!system.renameFile(filename, firstpart + "." + (filenum+1))) {
			logmsg("ERROR", resource.getString("LDAPSYNC.ERROR.RENAMING.OLD.LOG") + ": " + filename + " - " + system.lastError)
		}
	}

	var lastlist = lastlog.toArray()
	for (filename in lastlist) {
		task.logmsg("===> Rolling " + filename + " to " + filename + ".1")
		if (!system.renameFile(filename, filename + ".1")) {
			logmsg("ERROR", resource.getString("LDAPSYNC.ERROR.RENAMING.OLD.LOG") + ": " + filename + " - " + system.lastError)
		}
	}	
}	

function closeFile(filename) {
	var file = logFiles.getObject(filename)
	if (file != null) {
		if (file.getClass().getName().toLowerCase().indexOf("connector") > 0) {
			try {
				file.terminate()
			} catch (ex) {
				// do nothing
			}
		} else {
			try {
				file.close()
			} catch (ex) {
				// do nothing
			}
		}
	}
}	

function rollFile(tempFileName, totals) {
	var file;
	var fileName = tempFileName;

	try {
		closeFile(fileName);
	} catch (ex) {
		// ignore
	}		

	var p = fileName.indexOf(".temp")
	if (p > 0) {
		fileName = fileName.substring(0,p)
	}

	// if the Flow has done nothing then delete the log file
	if (totals == 0) {
		if (!system.deleteFile(tempFileName)) {
			logmsg("ERROR", resource.getString("LDAPSYNC.ERROR.DELETING.OLD.LOG") + ": " + tempFileName + " - " + system.lastError)
		}

		return;
	}

	if (tempFileName != fileName) {
		file = new java.io.File(tempFileName);
		var errorMsg = resource.getString("LDAPSYNC.ERROR.RENAMING.LATEST.LOG") + ": " + tempFileName;
		try {
			var testFile = openOutputFile(tempFileName, _appendToFile);
			testFile.close();

			if (simulate && !system.deleteFile(fileName)) {
				logmsg("ERROR", errorMsg + " <SIMULATE>");
			}	

			if (file.exists && !file.isDirectory()) {
				if (!system.renameFile(tempFileName, fileName)) {
					logmsg("ERROR", errorMsg);
				}
			}	
		} catch (ex) {
			logmsg("ERROR", errorMsg + " - " + ex);
		}	
	}	
}

function log(lvl, msg) {
	if (!utilsReady) {
		return
	}

	var now = new java.util.Date()
	var nowStr = system.formatDate(now, "yyyy-MM-dd'T'HH:mm:ss.SSSZ")

	if(typeof(msg) == "undefined"){
		msg = lvl;
		lvl = "INFO";
	}

	lvl = lvl.toUpperCase().trim();

	if (typeof(responseLogFile) != "undefined") {
		// May have to try a few times to get the writeback log opened in case other
		// writeback ALs are using it
		var retry = 60
		var wait = 1
		var wblogfilename = logDirectory + "/" + responseLogFile + ".log"

		do {
			try {
				wblogf = openOutputFile(wblogfilename, _appendToFile)
			} catch (ex) {
				var lastException = ex
				retry--
				wblogf = null
				system.sleep(wait)
			}
		} while (wblogf == null && retry > 0)

		if (wblogf == null) {
			java.lang.System.out.println(resource.getString("LDAPSYNC.ERROR.OPENING.RESPONSE.LOG.FILE") + ": " + wblogfilename + " - " + lastException)
			return
		}	
	} else {
		msg = where() + " - " + msg
	}	

	if (typeof(responseLogFile) != "undefined") {
		wblogf.write(lj(nowStr, 29) + " - " + lvl + " - " + msg)
		wblogf.newLine()
		wblogf.close()
	} else {	
		if (logf === null) {
			prepareLogFiles();
		}	

		try {
			logf.write(lj(nowStr, 29) + " - " + lvl + " - " + msg)
			logf.newLine()
			logf.flush()
		} catch (ex) {
			java.lang.System.out.println(resource.getString("LDAPSYNC.ERROR.WRITING.TO.LOG.FILE") + ": " + logf + " - " + ex);
		}	
	}	

	if (typeof(responseLogFile) === "undefined" && 
				(lvl.indexOf("FATAL") >= 0 || lvl.indexOf("ERROR") >= 0 || lvl.indexOf("WARN") >= 0)) {
		if (error.exception != null) {
			setException(error.exception, lvl)
		}

		try {
			errorf.write(lj(nowStr, 29) + " - " + lvl + " - " + msg);
			errorf.newLine();
			errorf.flush();
		} catch (ex) {
			java.lang.System.out.println(resource.getString("LDAPSYNC.ERROR.WRITING.TO.ERROR.LOG.FILE") + " - " + ex);
		}		

		if (typeof error !== "undefined" && error.exception !== null) {
			lastException = error;
		}	
	}


}

function setUserFriendlyTexts() { 
	userFriendlyText.push({lookfor: "java.net.MalformedURLException", 
							add: resource.getString("LDAPSYNC.URL.IS.INVALID")});

	userFriendlyText.push({lookfor: "java.net.ConnectException: Connection timed out: connect", 
							add: resource.getString("LDAPSYNC.SYSTEM.UNREACHABLE")});
	userFriendlyText.push({lookfor: "java.net.ConnectException: Connection refused: connect", 
							add: resource.getString("LDAPSYNC.SYSTEM.UNREACHABLE")});

	userFriendlyText.push({lookfor: "java.util.NoSuchElementException: No more tokens in String", 
							add: resource.getString("LDAPSYNC.SSL.IS.REQUIRED")});

	userFriendlyText.push({lookfor: "'Unauthorized'", 
							add: resource.getString("LDAPSYNC.USER.OR.PASSWORD.INCORRECT")});
	userFriendlyText.push({lookfor: "javax.naming.AuthenticationException", 
							add: resource.getString("LDAPSYNC.USER.OR.PASSWORD.INCORRECT")});
	userFriendlyText.push({lookfor: "javax.naming.AuthenticationException", 
							add: resource.getString("LDAPSYNC.USER.OR.PASSWORD.INCORRECT")});

	userFriendlyText.push({lookfor: "javax.net.ssl.SSLException", 
							add: resource.getString("LDAPSYNC.SPECIFIED.SSL.NOT.SUPPORTED")});
	userFriendlyText.push({lookfor: "javax.net.ssl.SSLHandshakeException", 
							add: resource.getString("LDAPSYNC.CLIENT.CERT.INCORRECT"), importcert : true}); 
	userFriendlyText.push({lookfor: "javax.naming.NameNotFoundException", 
							add: resource.getString("LDAPSYNC.SEARCH.BASE.IS.INVALID")});

	for (var i in userFriendlyText) {
		var thisText = userFriendlyText[i];
		thisText.lookfor = thisText.lookfor.toLowerCase();
		var parts = system.splitString(thisText.lookfor, ":");
		var lookArray = [];
		for (var part in parts) {
			lookArray.push(part);
		}
		thisText.lookfor = lookArray;
	}
}	

// add user friendly message for otherwise cryptic error text
function userFriendlyMsg(msg, baseurl) {
	var port = 443;
	if (userFriendlyText.length == 0) {
		setUserFriendlyTexts();
	}
	if (typeof baseurl !== "undefined" && baseurl != null) {
		var p = baseurl.indexOf(":", 9);
		if (p > 0) {
			var portstr = baseurl.substring(p+1);
			try {
				port = system.toInt(portstr);
			} catch (ex) {
				// do nothing
				java.lang.System.out.println("Invalid port value in base URL: " + baseurl);
			}		
			baseurl = baseurl.substring(0, p);
		}	
	}	
	var foundIt = false;
	var msgLC = msg.toLowerCase();
	var addTxt = "* not specified *";
	for (var i in userFriendlyText) {
		var thisText = userFriendlyText[i];
		addTxt = thisText.add;
		for (var j in thisText.lookfor) {
			var lookForText = thisText.lookfor[j];
			foundIt = msgLC.indexOf(lookForText) >= 0;
			if (!foundIt) {
				break;
			}	
		}	

		if (foundIt) {
			break;
		}	
	}

	if (!foundIt) {
		return msg;
	}	

	if (thisText.importcert && typeof baseurl !== "undefined" && baseurl != null) {
		var certmsg = "";
		try {
			certmsg = com.ibm.di.security.GetSSLCertificate.installCertificateFrom(baseurl, port);
			return resource.getString("LDAPSYNC.CLIENT.CERT.REQUESTED") 
					": " + certmsg + "\n- "
					+ resource.getString("LDAPSYNC.SDI.MUST.BE.RESTARTED")
					+ "\n-\n- " + msg;
		} catch (ex) {
			// @@TRANS TODO
			return resource.getString("LDAPSYNC.ERROR.REQUESTING.CERT")
					+ ": " + ex + "\n-\n- " + msg;
		}	
	}	

	return addTxt + "\n-\n-" + msg;
}	

function logmsg(lvl,msg){
	if(typeof(msg) == "undefined"){
		msg = lvl;
		lvl = "INFO";
	}

	lvl = lvl.toUpperCase();
	msg = msg.toString();

//	task.logmsg(lvl, where() + " - " + msg);

	var origMsg = msg;
	msg = userFriendlyMsg(msg);

	var useFlowKey = ""
	if (!("M".equals(flowKey)) && !("S".equals(flowKey)))
		useFlowKey = flowKey + ": "

	if (msg.indexOf("-@") < 0) {
		java.lang.System.out.println(" " + useFlowKey + msg);
	}	

	if (msg.toLowerCase().indexOf("java.lang.interruptedexception") >= 0) {
		syncAborted = true;
		lvl = "INFO";
	}	

	if (getPropertyDepth < 2 &&
		("FATAL".equals(lvl) || "ERROR".equals(lvl) || "WARN".equals(lvl))) {
		if (typeof work !== "undefined" && work !== null) {
			work.addAttributeValue("$error", lvl + ": " + msg);
		}		

		var hookEntry = system.newEntry();
		if (typeof work !== "undefined" || work !== null) {
			if (work !== null) {
				hookEntry.merge(work);
				hookEntry.setOperation(work.getOperation());
			}	
		}	
		if (typeof error !== "undefined") {
			hookEntry.setAttribute("$error", error);
			hookEntry.setAttribute("$errorMessage", msg);
			hookEntry.setAttribute("$where", where());
		}

		hookEntry.setAttribute("$level", lvl)

		invokeHook("hook.error", hookEntry);
		monitor("error", hookEntry);
	}	

	try {	
		log(lvl, msg)
	} catch (ex) {
		task.logmsg(lvl, where() + " - " + msg);
		task.logmsg("ERROR", resource.getString("LDAPSYNC.ERROR.WRITING.TO.LOG") + " - " + ex);
	}	
}

// some variables required for objectClass identification and handling
//
function prepareObjectClasses(){
	var propertyName = "source.container.objectClasses";
	var ocList = getProperty(propertyName, "ou=organizationalUnit, dc=dcObject, c=country, o=organization, cn=container");
	var msg
	if (ocList == null || ocList == ""){
		msg = resource.getString("LDAPSYNC.PROPERTY.IS.MISSING.OR.BLANK") + ": " + propertyRead
		logmsg("ERROR",msg);
		throw (where() + " - " + msg);
	}
	try{
		var ocParts = system.splitString(ocList, ",");
		for(var p in ocParts){
			var ocBits = system.splitString(p,"=");
			var key = ocBits[0].trim().toLowerCase();
			var val = ocBits[1].trim().toLowerCase();
			containerRDN.put(key,val);
			containerOC.put(val,key);
			containerRDNs += key + "\n";
		}
	} catch (ex){
		msg = resource.getString("LDAPSYNC.PROPERTY.IS.INVALID") + ": " + propertyRead
		logmsg("ERROR", msg)		
		throw (where() + " - " + msg);
	}
}	

function prepareList(pname, includeList) {
	var propertyName = pname;
	var containerList = new java.util.ArrayList()
	var conList = getProperty(propertyName,"");
	var msg
	var required = false // used to be an argument to the function
/*	
	if (conList == null || conList == ""){
		if (!required)
			return containerList
		msg = resource.getString("LDAPSYNC.PROPERTY.IS.MISSING.OR.BLANK") + ": " + propertyRead
		logmsg("ERROR",msg);
		throw (where() + " - " + msg);
	}
*/	
	try {
		var conLines = system.splitString(conList, "\n")

		for (var j = 0; j < conLines.length; j++) {
			var conLine = conLines[j].trim()
			var readList = system.splitString(conLine,";")
			for(var i=0; i < readList.length; i++){
				try {
					var c = cleanDN(readList[i].trim().toLowerCase());
				} catch (ex) {
					c = readList[i].trim().toLowerCase();
				}		
	//			containerList[i] = c+","+getProperty("source.ldap.searchBase").toLowerCase()
				containerList.add(c)
			}
		}	
	} catch (ex){
		msg = resource.getString("LDAPSYNC.PROPERTY.IS.INVALID") + ": " + propertyRead
		logmsg("ERROR", msg)		
		throw (where() + " - " + msg);
	}

	if (includeList && containerList.size() == 0) {
		// If found then first add the Endpoint searchbase. This is an implied Include
		var epSearchBase = getProperty("source.ldap.searchBase")
		if (epSearchBase != null) {
			containerList.add(cleanDN(epSearchBase.toLowerCase()))
		}	
	}

	return containerList.toArray()
}

function prepareContainerList() {	
	containerList = prepareList("source.containersToMigrate", true)
	containerListToSkip = prepareList("source.containersToSkip", false)
}

// returns true if the dn passed is one of those specified for processing
//
function useDN(dn, newSuperior){
	var dnLC = cleanDN(dn.toLowerCase());
	var useIt = false;
	var newSuperiorLC = (newSuperior) ? newSuperior.toLowerCase() : "";

	if (dnLC == sourceSearchBaseLC) {
		return false
	}	

	try {
		var ldapName = new javax.naming.ldap.LdapName(dn)
		var rdns = ldapName.getRdns()
		var rdn = rdns[rdns.size()-1].getType()
	} catch (ex) {
		logmsg("ERROR", resource.getString("LDAPSYNC.ERROR.PARSING.CONTAINER.DN") + ": " + ex + " - dn: " + dn)
		return false
	}

	if ( sourceSearchBaseLC != null && !dn.endsWith(sourceSearchBaseLC) &&
		 newSuperiorLC.length > 0 && !newSuperiorLC.endsWith(sourceSearchBaseLC ) ) {
		return false
	}	

	// if the Include list is empty, then accept this dn
	if (containerList.length == 0) {
		useIt = true
	} else 
	// if it's a container then do not filter
	if (containerRDN.get(rdn) != null){
		useIt = true
	// otherwise, see if the dn is valid according to the include list
	} else {
		for(var i=0; i<containerList.length && !useIt; i++){
			if(dnLC.indexOf(containerList[i])>=0){
				useIt =  true;
			}
		}
	}	

	if (!useIt && newSuperiorLC.length > 0) {
		var useSuperior = cleanDN(newSuperiorLC)
		for(var i=0; i<containerList.length && !useIt; i++) {
			if(useSuperior.indexOf(containerList[i])>=0) {
				useIt = true;
			}
		}
	}

	if (containerRDN.get(rdn) == null) {
		if (useIt && containerListToSkip.length > 0) {
			for (var i = 0; i < containerListToSkip.length && useIt; i++) {
				if (dnLC.indexOf(containerListToSkip[i]) >= 0)
					useIt = false
			}
		}
	}	

	return useIt;
}



// create suitable corrective measures message for an error
//
function correctionMsg(init, source, alConnector, error) {
	var errormsg = ""
	var errormsgLC = ""
	var ci = null
	var msg = ""
	var propPrefix = "target"
	if (source)
		propPrefix = "source"

	try {
		ci = alConnector.connector
	} catch (ex) {
		ci = alConnector
	}

	if (typeof(error) != undefined && error.message != null)
		errormsg = error.getString("exception") + ": " + error.getString("message");

	errormsgLC = errormsg.toLowerCase();

	if (errormsgLC.indexOf("ServiceUnavailableException") >= 0) {
		msg = resource.getString("LDAPSYNC.ENSURE.THAT.NOTHING.IS.BLOCKING.YOUR.ACCESS.TO.THE.SYSTEM.FOR.EXAMPLE.A.FIREWALL") + "\n"
				+ resource.getString("LDAPSYNC.OR.THAT.THE.SYSTEM.IS.RUNNING.AND.COMMUNICATION.PORTS.OPEN")
	}	
	else
	if (errormsgLC.indexOf("error code 1") >= 0) {
		msg = resource.getString("LDAPSYNC.MAKE.SURE.THAT.THE.SEARCH.BASE.IS.VISIBLE.IN.THE.SOURCE.SYSTEM.FOR.EXAMPLE.FROM.AN.LDAP.BROWSER") + "\n"
			  + resource.getString("LDAPSYNC.ALSO.ENSURE.THAT.THE.CREDENTIALS.DEFINED.FOR.THE.SOURCE.CONNECTION.ARE.AUTHORIZED.TO.SEE.ENTRIES.IN.THIS.CONTAINER")
	}
	else
	if (errormsgLC.indexOf("invalidsearch") >=0 ) {
		msg = resource.getString("LDAPSYNC.INVALID.SEARCH.FILTER.SPECIFIED") + " (" + propPrefix + ".ldap.searchFilter"
				+ ") -> " + alConnector.getName() + ": " + ci.getParam("ldapSearchFilter") + "\n"
	}
	else
	if (errormsgLC.indexOf("entry not found") >= 0) {
		msg = resource.getString("LDAPSYNC.MAKE.SURE.THAT.THE.PROPERTIES.SOURCE.USEROBJECTCLASS.AND.SOURCE.GROUPOBJECTCLASS.ARE.CORRECT")
	}
	else
	if (errormsgLC.indexOf("ssl") >= 0) {
		var ldapUrl = ci.getParam("ldapUrl").toLowerCase()
		if (ldapUrl.indexOf("ldaps://") >= 0) {
			msg = resource.getString("LDAPSYNC.SSL.MAY.NOT.BE.ENABLED.ON.SERVER") + ".\n"
					+ resource.getString("LDAPSYNC.ALSO.MAKE.SURE.THE.CLIENT.CERTIFICATE.FOR.THIS.SERVER.HAS.BEEN.IMPORTED.TO.THE.TDI.KEYSTORE") + "\n"
		} else {
			msg = resource.getString("LDAPSYNC.SSL.MAY.BE.ENABLED.ON.SERVER") + "\n"
		}
		msg += "   LDAP url = " + ci.getParam("ldapUrl") + "\n"
	}
	else
	if (errormsgLC.indexOf("error code 49") > 0)
		msg = resource.getString("LDAPSYNC.USERNAME.ANDOR.PASSWORD.PROPERTIES.ARE.INCORRECT") + "\n"
	else
	if (errormsgLC.indexOf("error code 32") > 0) {
		if (init) {
			var srchBase = ci.getParam("ldapSearchBase").toLowerCase();
			msg += resource.getString("LDAPSYNC.USERNAME.ANDOR.SEARCHBASE.PROPERTIES.ARE.INCORRECT") + "\n"
				  	+ "   " + propPrefix + ".ldap.searchBase = " + ci.getParam("ldapSearchBase") + "\n"
			if (srchBase.indexOf("cn=changelog") >= 0) {
				  msg += resource.getString("LDAPSYNC.NOTE.MAKE.SURE.THE.CHANGELOG.FEATURE.IS.ENABLED.FOR.THE.SOURCE.DIRECTORY.SERVER") + "\n"
		 	}
		} else {
			msg = resource.getString("LDAPSYNC.MAKE.SURE.THAT.THE.TARGET.SUFFIX.REFERENCES.A.NODE.THAT.EXISTS.IN.THE.TARGET") + "\n"
			if (preserveContainers) {
				msg += resource.getString("LDAPSYNC.MAKE.SURE.THAT.THE.USER.NAME.SPECIFIED.REFERENCES.A.PERSON.ENTRY.THAT.EXISTS.IN.THE.DIRECTORY") + "\n"
				msg += resource.getString("LDAPSYNC.ALSO.THAT.CONTAINERS.HAVE.BEEN.MIGRATED.BEFORE.PERSON.OR.GROUP.ENTRIES") + "\n"
			}
		}
	} 

	if (errormsg.length > 0) {
		msg = errormsg + "\n" + msg;
	}	

	msg += "\n" + entryDump("ERROR", error)

	if (typeof(conn) != "undefined") {
		msg += entryDump("CONN", conn)
	}

	if (typeof(work) != "undefined") {
		msg += entryDump("WORK", work)
	}	

	if (typeof(thisConnector) != "undefined" && thisConnector != null)
		msg += connectorParams(thisConnector.connector)

	return msg + "\n"
}

spaces = "                                                                                                                                "
function rjfill(msgtxt, len, filler, contdStr) {
	var txt = String(msgtxt)
	if (txt.length > len && typeof(contdStr) != "undefined") {
		txt = txt.substring(0, len-contdStr.length) + contdStr
	}
	if (len <= txt.length) {
		return txt
	} else {
		var targetlen = (len-txt.length)
		var filltxt = ""
		while (filltxt.length < targetlen) {
			filltxt += filler
		}	
		return filltxt.substring(0, targetlen) + txt
	}	
}

function rj(msgtxt, len, contdStr) {
	return rjfill(msgtxt, len, spaces, contdStr)
}

function ljfill(msgtxt, len, filler) {
	var txt = String(msgtxt)

	if (typeof(filler) == "undefined") {
		filler = " "
	}	

	if (txt.length > len && typeof(contdStr) != "undefined") {
		return txt.substring(0, len-contdStr.length) + contdStr
	} else
	if (len <= txt.length) {
		return txt
	} else {
		var targetlen = (len-txt.length)
		var p = txt.length % filler.length
		var filltxt = filler.substring(p, Math.min(targetlen, filler.length))
		while (filltxt.length < targetlen) {
			filltxt += filler
		}	
		return txt + filltxt.substring(0, targetlen)
	}	
}	

function lj(msgtxt, len, contdStr) {
	return ljfill(msgtxt, len, spaces, contdStr)
}

function allValues(att) {
	var val = ""

	if (att != null)
		for (var i = 0; i < att.size(); i++)
			val += "  '" + att.getValue(i) + "'"

	return val.trim()
}

function entryDump(entryName, entry) {
	var dmp = ""

	if (typeof(entry) == "undefined" || entry == null)
		return ""

	if (entry.size() == 0)
		return ""

	var attNames = entry.getAttributeNames();
	java.util.Arrays.sort(attNames)

	if (entryName == "ERROR") {
		entry.assemblyline = task.getShortName();
	}	

	dmp = "***** " + resource.getString("LDAPSYNC.START.DUMPING") + ": " + entryName + " *****\n"
	dmp += entry.toString()
/*	
	for (var n in attNames) {
		dmp += rj(n,25) + ": " + allValues(entry.getAttribute(n)) + "\n"
	}
*/	 
	dmp += "***** " + resource.getString("LDAPSYNC.END.DUMPING") + ": " + entryName + " *****\n"

	return dmp
}

function addGroupMembersToAttribute(entry, toMem) {
	var attnames = entry.getAttributeNames()
	var fromMem = null
	for (var n in attnames)
		 if (n.startsWith("member;") || n.equalsIgnoreCase("member")) {
			fromMem = e.getAttribute(n)
			if (fromMem.size() > 0) {
				break
			}
		}

	if (fromMem != null) {
		for (var i = 0; i < fromMem.size(); i++) {
			var thisMem = fromMem.getValue(i)
			if (!toMem.hasValue(thisMem))
				toMem.addValue(thisMem)
		}	
		if (deBug) logmsg("--@@--> Adding " + fromMem.size())
	}
	if (deBug) logmsg("--@@--> Total group members after addGroupMembers call: " + toMem.size())
}

function parseMemberRange(entry) {
	var attnames = entry.getAttributeNames()
	var bigGroup = false
	var n

	for (n in attnames)
		if (n.startsWith("member;")) {
			bigGroup = true
			break
		}

	if (!bigGroup)
		return ""

	var fromstr = n.substring(7)
	var p = fromstr.indexOf("-")
	var tostr = fromstr.substring(p+1)
	fromstr = fromstr.substring(0,p)
	p = fromstr.indexOf("=")
	fromstr = fromstr.substring(p+1)

	if (tostr == "*")
		return ""

	var fromval = system.toInt(fromstr)
	var toval = system.toInt(tostr)
	var range = toval-fromval+1

	return "member;range=" + (fromval+range) + "-" + (toval+range)
}

function readProperty(pname, defValue, flowStub) {
	propertyRead = flowStub.trim() + pname.trim()
	var p = system.getTDIProperties().getPropertyEntry(propertyRead)
	if (p != null)
		p = p.getObject("value")

	if (p == null) {
		propertyRead = pname
		if (typeof(defValue) == "undefined" || defValue == null)
			p = null
		else {
			p = defValue
		}	
	} 	

	if (p != null) {
		try {
			var trimmedp = p.toString().trim()
			p = trimmedp
		} catch (ex) {
			// do nothing
		}
	}

	return p
}

var getPropertyName = "* undefined *";
var getPropertyDepth = 0;
function getProperty(pname, defValue, asString) {
	if (typeof defValue === "undefined") { defValue = null }
	if (typeof asString === "undefined") { asString = true } 
	getPropertyDepth++;
	var p;

	getPropertyName = pname;

	var useFlowKey = null;	
	if (typeof(flowKey) != "undefined" && flowKey != null /* && flowKey.length > 0 */) {
		useFlowKey = flowKey;
	}

	if (useFlowKey === null) {
		if (alTCB != null) {
			useFlowKey = alTCB.getString("$flowKey");
		}	
		if (useFlowKey === null) {
			logmsg("ERROR","utils::getProperty() - " + resource.getString("LDAPSYNC.ERROR.RETRIEVING.PROPERTY") + ": " + pname
					+ " - " + resource.getString("LDAPSYNC.FLOWKEY.IS.UNDEFINED"))
			throw where() + " - " + resource.getString("LDAPSYNC.FLOWKEY.IS.UNDEFINED")
		}	
	}

	var flowStub = useFlowKey.length == 0 ? "" : (useFlowKey + ".")

	if (asString) {
		p = opEntry.getString(pname);
	} else {
		p = opEntry.getObject(pname);
	}		

	if (p === null) {
		if (asString) {
			p = opEntry.getString(flowStub + pname);
		} else {
			p = opEntry.getObject(flowStub + pname);
		}		
	}
/*	
	if (p === null) {
		var altPname = getAlternativeProperty(pname);
		if (altPname !== null) {
			p = getProperty(altPname);
		}	
	}	
*/
	if (p === null) {
		propertyRead = pname
		if (defValue == null)
			p = null
		else
			p = defValue
	}	


	if (asString) {	
		if (p !== null) {		
			try {
				var ptrimmed = p.toString().trim()
				p = ptrimmed
			} catch (ex) {
				// do nothing
			}
		}

		getPropertyDepth--;
		return correctPropertyValue(pname, p)
	} else {
		getPropertyDepth--;
		return p;
	}		
}

function getPropertyObject(pname, defValue) {
	if (typeof defValue === "undefined") { defValue = null } 
	return getProperty(pname, defValue, false);
}	

function getAlternativeProperty(pname) {
	var altProp = null;
	var checkProp = pname;
	do {
		checkProp = alternativeProperties.get(checkProp);
		if (checkProp !== null) {
			altProp = checkProp;
		}	
	} while (checkProp !== null);
	return altProp;	
}	

function correctPropertyValue(pname, pvalue) {
	var pnameLC = (pname || "").toLowerCase()
	var pvalueLC = (pvalue || "").toLowerCase()
	// fix for LDAP URL properties
	if (pnameLC.endsWith("ldapurl") || pnameLC.endsWith("ldap.url")) {
		if (!pvalueLC.startsWith("ldap://") && !pvalueLC.startsWith("ldaps://")) {
			pvalue = "ldap://" + pvalue;
		}	
	}	
	return pvalue;
}	

function connectorParam(pname, defValue) {
	var pVal = getProperty(pname, null)

	if (pVal == null) {
		if (typeof(defValue) == "undefined") {
			return "* undefined property: " + propertyRead + " *"
		} else {
			if ("statekey".equalsIgnoreCase(defValue)) {
				var cdType = getProperty("source.changeDetectionType","")
				if (cdType.length > 0)
					cdType = "_" + cdType
				var stateKeyPropVal = getProperty("source.ldap.stateKey","STATEKEY")
				return flowKey + "_" + stateKeyPropVal
			} else {
				return defValue
			}
		}
	} else {
		if ("statekey".equalsIgnoreCase(defValue)) {
			pVal = flowKey + "_" + pVal
		}	
	}

	return pVal	
}

function getIntProperty(pname, defValue, minValue) {
	var pVal = getProperty(pname);
	var intVal = null;

	if (typeof(defValue) == "undefined") {
		defValue = null;
	}	

	try {
		intVal = system.toInt(pVal)
	} catch (ex) {
		intVal = null
	}

	if (intVal == null || (minValue && intVal < minValue)) {
		intVal = defValue;
	}	

	return intVal
}

function getArrayProperty(pname, delimiter) {
	var pVal = getProperty(pname)

	if (typeof(delimiter) == "undefined")
		delimiter = ","

	if (pVal != null) {
		var arrayVal = null
		arrayVal = system.splitString(pVal, delimiter)
	}

	return arrayVal
}

function randomRangeInt(low, high) {
	var diff = high - low + 1;
	var rand = Math.random()*diff;
	return Math.ceil(rand) + low - 1;
}

function dnLC(dn, failOnError) {
	failOnError = failOnError || false;
	try {
		var fixeddn = new javax.naming.ldap.LdapName(dn).toString().toLowerCase();
		return cleanDN(fixeddn)
	} catch (ex) {
		if (failOnError) {
			throw "dnLC() failure! - " + dn + " - " + ex;
		} else {
			return "";
		}	
	}	
}

function cleanDN(dn, errormsg) {
	if (dn == null) {
		if (typeof(errormsg) != "undefined") {
			throw "utils:cleanDN() - " + errormsg
		}
		return null	
	}	

	try {
		var cleandn = new javax.naming.ldap.LdapName(dn)
		dn = new javax.naming.ldap.LdapName(cleandn.getRdns()).toString()
	} catch (ex) {
		throw where() + " - " + resource.getString("LDAPSYNC.ERROR.PARSING.DN.TO.TRANSLATE.IT") + ": " + ex + " - DN: " + dn
	}	

	return dn
}

function cleanRDN(rdn, errormsg) {
	if (rdn == null) {
		if (typeof(errormsg) != "undefined") {
			throw "utils:cleanDN() - " + errormsg
		}
		return null	
	}	
	try {
		var cleanrdn = new javax.naming.ldap.LdapName("cn=" + rdn + ",o=fds.com");
		var rdns = cleanrdn.getRdns();
		rdn = rdns.get(rdns.size()-1).getValue();
	} catch (ex) {
		throw where() + " - " + resource.getString("LDAPSYNC.ERROR.CLEANING.RDN") + ": " + rdn + " - " + ex;
	}	

	return rdn
}

function where() {
	var comp = ""

	if (typeof(thisComponent) != "undefined" && thisComponent != null)
		comp += "/" + thisComponent.getName()

	if (comp == "")
		comp = "/<?Unknown?>"

	return "[" + task.getShortName() + comp + "]"	
}

function translateDN(oldDN, useRDN, rdnValue, useSuffix, newSuperior, newrdn) {
	var p, dn, targetSuffix, targetDN;
	if (typeof(newrdn) != "undefined" && newrdn != null) {
		rdnValue = newrdn
		p = rdnValue.indexOf("=")
		if (p > 0)
			rdnValue = rdnValue.substring(p+1).trim()
	}	

	var p = useRDN.indexOf("=")
	if (p > 0)
		useRDN = substring(0,p).trim()

	if (preserveContainers){
		dn = oldDN // @@@@ maybe this should be work instead

		targetDn = useRDN + "=" + rdnValue + ","
		try {
			var oldRdns = new javax.naming.ldap.LdapName(dn).getRdns()
		} catch (ex) {
			throw where() + " - " + resource.getString("LDAPSYNC.ERROR.PARSING.DN.TO.TRANSLATE.IT") + ": " + ex + " - dn: " + dn
		}	

		targetSuffix = ""

		if (typeof(newSuperior) != "undefined" && newSuperior != null) {
			var supRdns

			try {
				supRdns = new javax.naming.ldap.LdapName(newSuperior).getRdns()
			} catch (ex) {
				throw where() + " - " + resource.getString("LDAPSYNC.ERROR.PARSING.NEWSUPERIOR") + ": " + ex + " - newSuperior: " + newSuperior
			}	
			var len = sourceSuffixRdns.size()

			for (var i = supRdns.size()-1; i >= len; i--) {
				targetSuffix += supRdns.get(i).toString().trim()+","
			}
		} else {
			var len = sourceSuffixRdns.size()

			for (var i = oldRdns.size()-2; i >= len; i--) {
				targetSuffix += oldRdns.get(i).toString().trim()+","
			}
		}	

		targetSuffix = targetSuffix.replace(/CN=/g,"OU=")

		targetDn += targetSuffix + useSuffix;
	} else {	
		targetDn = useRDN + "=" + rdnValue + "," + useSuffix
	}	

	var returnDN = ""
	try {
		returnDN = new javax.naming.ldap.LdapName(targetDn).toString()
	} catch (ex) {
		throw where() + " - " + resource.getString("LDAPSYNC.ERROR.PARSING.TARGETDN") + ": " + ex + " - targetDn: " + targetDn		
	}

	return returnDN
}

var showParams = ["ldapUrl","ldapUsername","ldapSearchBase","ldapSearchFilter","ldapSearchScope","ldapSizeLimit","ldapPageSize","jndiExtraProviderParams"]
function connectorParams(ctr) {
	if (typeof(ctr) == "undefined" || ctr == null)
		return ""

	var strBuf = new java.lang.StringBuffer("***** " + resource.getString("LDAPSYNC.CONNECTOR.PARAMETERS") + ": " + ctr.getName() + " *****\n")
	var p
	for(var i = 0; i < showParams.length; i++){
		p = showParams[i]
		strBuf += "    " + p + ": " + ctr.getParam(p) + "\n"
	}
	return strBuf.toString()
}

function addLinkedAttributes(wrk, cnn, targetRDN, rdnValue, changeDetType, newrdn, newSuperior, typeOfEntry) {
	var sourceGUID

	if (typeof(typeOfEntry) == "undefined") {
		typeOfEntry = "not person"
	}

	cnn[targetRDN] = rdnValue

	sourceGUID = work.getObject(auxLinkedGUIDSourceAttribute)
	if (sourceGUID != null && "objectguid".equals(auxLinkedGUIDSourceAttribute.toLowerCase()) && !typeof sourceGUID === "string") {
		try {
			sourceGUID = system.binaryGUIDtoString(sourceGUID)
		} catch (ex) {
			sourceGUID = null
		}		
	}	

	if (typeof(newSuperior) == "undefined")
		newSuperior = null
	if (typeof(newrdn) == "undefined")
		newrdn = null

	var dn = wrk.getString("$dn")
	if (newrdn != null) {
		if (newSuperior != null) {
			dn = newrdn + "," + newSuperior
		} else {
			var ldapName = javax.naming.ldap.LdapName(dn)
			var rdns = ldapName.getRdns()
			ldapName.remove(rdns.size()-1)
			dn = newrdn + "," + ldapName.toString()
		}
	}

	if (deBug) logmsg("--@@-->> linked dn: " + dn + " - newSuperior: " + newSuperior + "  newrdn: " + newrdn)

	cnn[auxLinkedDNAttribute] = cleanDN(dn.toLowerCase());

	if (targetIsLDAP) {
		var oc = cnn.getAttribute("objectClass")
		if (oc != null && !oc.hasValue(auxLinkedEntryClassName)) {
			oc.addValue(auxLinkedEntryClassName)
			if (writePTAAttributes && "person".equals(typeOfEntry)) {
				oc.addValue("ibm-ptaReferral")
			}	
		}	

		if (writePTAAttributes && "person".equals(typeOfEntry)) {
			cnn["ibm-ptaLinkAttribute"] = "_DN_"
			cnn["ibm-ptaLinkValue"] = cleanDN(dn.toLowerCase())
		}
	}	

	if (sourceGUID != null) {
		cnn.setAttribute(auxLinkedGUIDAttribute, sourceGUID)
	}	
}

function getBooleanProperty(pname, defValue) {
	if (typeof(defValue) == "undefined") {
		defValue = false;
	}

	defValue = String(defValue).trim();

	var pval = getProperty(pname, defValue);

	if (pval === null) {
		pval = defValue;
	} 

	return "true".equalsIgnoreCase(pval) || "yes".equalsIgnoreCase(pval);
}	

writebackStateKey = "writeback.stateKey"
function loadProperties() {
	// Initial Sync (migrate) or Incremental (isSync == true)
	isSync = getBooleanProperty("synchronize", false);

	changeDetType = getProperty("source.changeDetectionType","delta").toLowerCase();
	changeDetectionType = changeDetType;

	debugging = getBooleanProperty("debugging", "false");

	determineTarget();

	preserveContainers = !cloudSync 
						&& targetIsLDAP 
						&& "true".equalsIgnoreCase(getProperty("mirroring.enabled")) && "true".equalsIgnoreCase(getProperty("global.preserveSourceContainers"));

	var dir = main.getMetamergeConfig().getDirectory()
	if (dir != null)
		configDirectory = dir
	configDirectory = "LDAPSync"

	// get log directory path
	logFilepath = getProperty("global.logDirectory")
	if (logFilepath == null)
		logFilepath = configDirectory + "/logs/"
	logFilepath = logFilepath.trim()
	if (logFilepath.endsWith("/") || logFilepath.endsWith("\\"))
		logFilepath  = logFilepath.substring(0,logFilepath.length-1)
	logDirectory = logFilepath

	try {
		var logdir = new java.io.File(logDirectory)
		if (!logdir.exists()) {
			logdir.mkdir()
		}	
	} catch (ex) {
	}		

	// get global.maxLogFiles property value as integer - default is 20
	maxLog = getProperty("global.maxLogFiles")
	try {
		maxLog = system.toInt(maxLog)
	} catch (ex) {
		maxLog = null
	}
	if (maxLog == null || !(maxLog > 0 && maxLog < 99999)) {
		maxLog = 20
	}

	sourceSearchBase = cleanDN(getProperty("source.ldap.searchBase"))
	if (sourceSearchBase != null) {
		sourceSearchBaseLC = sourceSearchBase.toLowerCase()
	} else {
		sourceSearchBaseLC = null
	}

	sourceUserObjectClass = getProperty("source.userObjectClass");
	if (sourceUserObjectClass != null)
		sourceUserObjectClass = sourceUserObjectClass.toLowerCase()
	else
		sourceUserObjectClass = "inetorgperson"

	if (cloudSync) {
		sourceUserObjectClass = "person";
		opEntry[flowKey + "source.userObjectClass"] = sourceUserObjectClass;
	}		

	sourceGroupObjectClass = getProperty("source.groupObjectClass");
	if (sourceGroupObjectClass != null)
		sourceGroupObjectClass = sourceGroupObjectClass.toLowerCase()
	else
		sourceGroupObjectClass = "groupofuniquenames"

	if (cloudSync) {
		targetRootSuffix = "dc=SCIM.IBM.COM";
		sourceGroupObjectClass = "group";
		opEntry[flowKey + "source.groupObjectClass"] = sourceGroupObjectClass;
	} else {
		targetRootSuffix = cleanDN(getProperty("target.ldap.searchBase"));
	}

	if(cloudSync || preserveContainers){
		targetSuffixForUsers = targetRootSuffix;
		targetSuffixForGroups = targetRootSuffix;
	} else {
		targetSuffixForUsers = getProperty("target.suffixForUsers", null) || targetRootSuffix;
		targetSuffixForGroups = getProperty("target.suffixForGroups", null) || targetRootSuffix;
	}

	// Password cache settings
	var pwdCacheSetting = getProperty("password.cache.enabled");
	if (pwdCacheSetting !== null && pwdCacheSetting.trim().length > 0) {
		var cacheTrees = system.splitString(pwdCacheSetting,"&&");
		if (cacheTrees !== null) {
			for (var tree in cacheTrees) {
				try {
					var treeName = new javax.naming.ldap.LdapName(tree);
					var compName = new javax.naming.ldap.LdapName(targetRootSuffix);
					if (treeName.equals(compName)) {
						passwordCaching = true;
						break;
					}

					compName = new javax.naming.ldap.LdapName(targetSuffixForUsers);	
					if (treeName.equals(compName)) {
						passwordCaching = true;
						break;
					}
				} catch (ex) {
					if (deBug) logmsg("ERROR", "--**--> Error parsing password cache enablement"
										+ " - PTA tree:" + tree
										+ " - Root suffix: " + targetRootSuffix
										+ " - Users suffix: " + targetSuffixForUsers);
				}		
			}	
		}	
	}	

	// Aux class information for linking central Person data to source entries
	auxLinkedEntryClassName = getProperty("target.ldap.auxLinkedEntryClassName", "activedirectorylinkedentry")
	auxLinkedDNAttribute = getProperty("target.ldap.auxLinkedDNAttribute", "adDn")
	auxLinkedGUIDAttribute = getProperty("target.ldap.auxLinkedGUIDAttribute", "adObjectGUIDStr")
	auxLinkedGUIDSourceAttribute = getProperty("source.ldap.auxLinkedGUIDAttribute", "objectGUID")

	targetLinkAttribute = getProperty("target.link.attribute");
	sourceLinkAttribute = getProperty("source.link.attribute");

	// RDN attributes used for source and target
	targetUserRDN = getProperty("target.userRDN","uid")
	sourceUserRDN = getProperty("source.userRDN",targetUserRDN)

	// Object class information
	targetUserObjectClass = getProperty("target.userObjectClass", "inetOrgPerson");
	targetGroupObjectClass = getProperty("target.groupObjectClass", "groupOfUniqueNames");
	targetGroupMemberAttribute = getProperty("target.groupMemberAttribute")
	if (targetGroupMemberAttribute == null) {
		if (targetGroupObjectClass.toLowerCase() == "groupofuniquenames")
			targetGroupMemberAttribute = "uniqueMember"
		else
			targetGroupMemberAttribute = "member"
	}

	// Retrieve list of RDNs from source search base - used for DN translation
	if (sourceSearchBase != null && targetIsLDAP && sourceSearchBase.length > 0) {
		try {
			sourceSuffixRdns = new javax.naming.ldap.LdapName(sourceSearchBase).getRdns()
		} catch (ex) {
			throw where() + " - " + resource.getString("LDAPSYNC.ERROR.PARSING.SOURCE.SEARCHBASE") + ": " + ex + " - source searchBase: " + sourceSearchBase
		}	
	}	

	// Does this source support PTA (including VirtualPTA)
	writePTAAttributes = getBooleanProperty("supportsPTA", false);

	// Join controls
	performJoin = getBooleanProperty("join.perform", false);
	ifJoinFails = getProperty("join.failure","skip").toLowerCase().trim()

	// Whether to perform timing measurements and reporting
	doTiming = getBooleanProperty("timing.enabled", false);

	// now for the UserSync properties
	getGroupFilters();
	getAttributeFilters();

	// Set up which types are to be handled for this flow run
	// Note that for CloudSync we always skip groups (for now)
	handleType.person = getBooleanProperty("source.handlePersonObjects", false);
	handleType.group = getBooleanProperty("source.handleGroupObjects", false) || filterOnGroups;

	if (preserveContainers && !cloudSync) {
		handleType.container = true;
	} else {
		handleType.container = false;
	}	

	// CloudSync settings
	getCloudSyncSettings();

	// retryList settings
	getRetryListSettings();
}

function getRetryListSettings() {
	processRetryList = !"false".equals(getProperty("source.retrylist.read"));
	saveRetryList = !"false".equals(getProperty("source.retrylist.save"));
	processLiveData = !"false".equals(getProperty("source.livedata.read"));
}	

function getCloudSyncSettings() {
	csUserMailShot = "true".equalsIgnoreCase(getProperty("smtp.enabled"));

//	csUserMailShot = true; // DEBUG ------------------------------------------------

	csSMTPhost = getProperty("smtp.smtpServerHost");
	csSMTPport = getProperty("smtp.smtpServerPort");
	csSMTPssl = !"false".equalsIgnoreCase(getProperty("smtp.ssl"));
	if (csSMTPport == null) {
		if (csSMTPssl) {
			csSMTPport = 645;
		} else {	
			csSMTPport = 25;
		}	
	}	
	csSMTPuser = getProperty("smtp.username");
	csSMTPpassword = getProperty("smtp.password");
	csSMTPfrom = getProperty("smtp.from");
	if (csSMTPfrom == null) {
		csSMTPfrom = "fds@ibm.com"
	}	
}	


// requests the client cert from the service and installs it into the SDI keystore
function getCertificate (url, port) {
	var usePort = system.toInt(port);
	var msg = com.ibm.di.security.GetSSLCertificate.installCertificateFrom(url, usePort);
	return msg;
}


var sendMailFC = null;
function csMailShot(entry, 
					optMail, optSubject, optBody) { // optional arguments
	var result = {
		status: "failed"
	}

	if (!entry || entry == null) {
		entry = system.newEntry();
	}	

	if (!csUserMailShot && typeof optMail === "undefined") {
		return result;
	} else
	if (typeof entry === "undefined" || entry == null || entry.size() == 0) {
		logmsg("WARN",resource.getString("CLOUDSYNC.ENTRY.MISSING.DATA"));
		result.error = resource.getString("CLOUDSYNC.ENTRY.MISSING.DATA");
		return result;
	}

	result.status = "failure";

	var entryForEvaluation = system.newEntry();
	entryForEvaluation.merge(entry);
	if (entryForEvaluation.password == null) entryForEvaluation.password = entry.userPassword;
	if (entryForEvaluation.userid == null) entryForEvaluation.userid = entry.uid;
	if (entryForEvaluation.username == null) entryForEvaluation.username = entry.cn ? entry.cn : entry.displayName;

	if (typeof optMail === "undefined" || optMail == null) {
		var mail = entry.getString("mail");
	} else {
		var mail = optMail;
	}		

	if (mail == null) {
		logmsg("WARN", resource.getString("CLOUDSYNC.ENTRY.MISSING.MAIL.ATTRIBUTE") + ": " 
				+ entry.getString("$dn"));
		result.error = resource.getString("CLOUDSYNC.ENTRY.MISSING.MAIL.ATTRIBUTE") + ": " 
				+ entry.getString("$dn");
		return result;
	}	

	// prepare mail
	var msg = resource.getString("CLOUDSYNC.NEW.USER.MAIL.MESSAGE") + " - ";
	var body;
	var subject;

	if (typeof optBody !== "undefined" && optBody != null) {
		body = optBody;
	}	
	body = evaluateProperty("smtp.body", entryForEvaluation, msg + resource.getString("CLOUDSYNC.ERROR.WITH.BODY"));

	if (typeof optSubject !== "undefined" && optSubject != null) {		
		 subject = optSubject;
	}		
	subject = evaluateProperty("smtp.subject", entryForEvaluation, msg + resource.getString("CLOUDSYNC.ERROR.WITH.SUBJECT"));

	// send the mail
	var e = system.newEntry();
//	e.smtpServerHost = csSMTPhost;		
//	e.smtpServerPort = String(csSMTPport);
	e.from = csSMTPfrom;
	e.replyTo = csSMTPfrom;		
	e.body = (body && body != null) ? body : "{work.password}";
	e.subject = (subject && subject != null) ? subject : "{work.username}";
	e.recipients = mail;

	// if first time then set up the FC
	var certImport = null;
	var retry = 1;
	var sentOk = false;
	do {
		if (sendMailFC == null) {
			try {
				sendMailFC = system.getFunction("ibmdi.SendEMailFC");
				sendMailFC.setParam("smtpServerHost", csSMTPhost);
				sendMailFC.setParam("smtpServerPort", String(csSMTPport));
				sendMailFC.setParam("username", csSMTPuser);
				sendMailFC.setParam("password", csSMTPpassword + "");
				sendMailFC.setParam("useSSL", csSMTPssl ? "true" : "false");

//java.lang.System.out.println("csMailShot - SSL: " + sendMailFC.getParam("useSSL") + "   smtp: " + sendMailFC.getParam("smtpServerHost") + ":" + sendMailFC.getParam("smtpServerPort"));				

				sendMailFC.initialize(null);
			} catch (ex) {
				logmsg("ERROR", resource.getString("CLOUDSYNC.ERROR.IN.MAILSHOT.INIT")
							+ " - " + ex);
				csUserMailShot = false;
				result.error = resource.getString("CLOUDSYNC.ERROR.IN.MAILSHOT.INIT")
							+ " - " + ex;
				return result;
			}
		}	

		try {
			if (deBug) {
				java.lang.System.out.println("--> auto mailshot to " + mail); // @@TODO remove debug code
			}	
			var retE = sendMailFC.perform(e);
			sentOk = true;
		} catch (ex) {
			var exstr = ex.toString().toLowerCase();
			if (ex instanceof javax.net.ssl.SSLHandshakeException) {
				var msg = getCertificate("https://" + csSMTPhost, csSMTPport);
				logmsg("ERROR", resource.getString("CLOUDSYNC.CERT.IMPORTED")
						+ " - " + msg);
				result.error = resource.getString("CLOUDSYNC.CERT.IMPORTED")
						+ " - " + msg;
			} else	
			if (exstr.indexOf("javax.net.ssl.sslexception") >= 0 && csSMTPssl) {
				csSMTPssl = false;
				opEntry[flowKey + ".smtp.ssl"] = "false";
				try {
					sendMailFC.terminate();
				} catch (ex2) {
					// do nothing
				}	
				sendMailFC = null;	
				java.lang.System.getProperties().remove("mail.smtp.socketFactory.class");
				continue;
			} else {
				logmsg("ERROR", resource.getString("CLOUDSYNC.ERROR.SENDING.MAIL")
						+ ": " + work.getString("$dn") + " - " + ex);
				result.error = resource.getString("CLOUDSYNC.ERROR.SENDING.MAIL")
						+ ": " + work.getString("$dn") + " - " + ex;
			}	

			return result;
		}	

	} while (!sentOk && retry-- > 0);	

	var status = retE.getString("status");

	if (!"ok".equalsIgnoreCase(status))	{
		logmsg("ERROR", resource.getString("CLOUDSYNC.ERROR.SENDING.MAIL")
				+ ": " + work.getString("$dn") + " - " + status);
		result.error = resource.getString("CLOUDSYNC.ERROR.SENDING.MAIL")
				+ ": " + work.getString("$dn") + " - " + status;
		return result;
	}

	result.status = "success";
	return result;
}	

function evaluateProperty(pname, entry, errormsg) {
	var pval = getProperty(pname);
	var psubst = pval;
	if (pval == null) {
		logmsg("!! Cannot perform CloudSync mailShot - property not set: " + pname + " !!");
		return pval;
	}

	try {
		psubst = evaluate(entry, pval);
	} catch (ex) {
		logmsg("ERROR", errormsg + " (" + pname + ") - " + ex);
		return pval;
	}

	return psubst;
}

function addDNtoArray(dn, arr) {
	var inError = false;
	try {
		cleaned = cleanDN(dn);
		dn = cleaned;
		inError = false;
	} catch (ex) {
		logmsg("WARN", resource.getString("LDAPSYNC.GROUP.FILTER.INVALID") + ": " + dn);
		addToStats(flowKey, "warn", "warn");
		inError = true;
	}

	if (!inError) {
		arr.push(dn);
	}	
}		

function getGroupFilters() {
	var useGroupFilter = "true".equalsIgnoreCase(getProperty("filter.groups.enabled"));

	groupFilters = new Array();
	syncGroupsList = new Array();

	// get group list for filtering users
	filterOnGroups = false;
	if (useGroupFilter) {
		var groups = getProperty("filter.groups");
		if (groups != null && groups.trim() != "") { 
			var parts = system.splitString(groups, "\n");

			for (var part in parts) {
				part = part.trim();
				if (part.length > 0) {
					addDNtoArray(part, groupFilters);
				}	
			}
		}	

		if (groupFilters != null && groupFilters.length > 0) {
			filterOnGroups = true;
		}
	}	

	// get group list for sync'ing groups (CloudSync)
	syncGroupsListEnabled = "true".equalsIgnoreCase(getProperty("source.handleGroupObjects"));
	if (syncGroupsListEnabled) {
		var syncGroupsListProp = getProperty("sync.groups");
		if (syncGroupsListProp != null && syncGroupsListProp.trim() != "") {
			var parts = system.splitString(syncGroupsListProp, "\n");

			for (var part in parts) {
				part = part.trim();
				if (part.length > 0) {
					addDNtoArray(part, syncGroupsList);
				}
			}	
		}

		if (syncGroupsList == null || syncGroupsList.length == 0) {
			syncGroupsListEnabled = false;
		}
	}	
}

function getAttributeFilters() {
	var useAttributeFilter = "true".equalsIgnoreCase(getProperty("filter.attributes.enabled"));

	if (!useAttributeFilter) { return; } 

	for (var i = 0; i < 9; i++) {
		var attFilter = getProperty("filter.attribute." + i);
		if (attFilter === null || attFilter.trim() == "") { 
			continue; 
		}
		var parts = attFilter.split("||");
		if (parts.length == 3) {
			var filter = {};
			filter.name = parts[0].trim();
			filter.operator = parts[1].trim();
			filter.value = parts[2].trim().toLowerCase();

			if (filter.name.length > 0) {
				if (!validAttributeOperator(filter.operator)) {
					logmsg("ERROR", resource.getString("LDAPSYNC.INVALID.ATTRIBUTE.OPERATOR") + ": "
						+ "<" + filter.name + ">" + "  " + filter.operator + "  '" + filter.value + "'");
					addToStats(flowKey, "error", "error");
					continue;
				}

				if (attributeFilters === null) {
					attributeFilters = new Array();
					filterOnAttributes = true;
					filterAttributesOR = "true".equalsIgnoreCase(getProperty("filter.or"));
				}

				attributeFilters[attributeFilters.length] = filter;
			}	
		}
	}	
}

function validAttributeOperator(op) {
	switch (op.toLowerCase()) {
		case "equals": 
		case "contains": 
		case "startswith": 
		case "endswith": 
		case "hasvalue":
		case "not_equals": 
		case "not_contains": 
		case "not_startswith": 
		case "not_endswith": 
		case "not_hasvalue": return true;
		default: return false;
	}
}	

function checkScope(sourceDN, sourceLDAP, changeDetType) {
	var entry = null;

	if (!useDN(sourceDN)) {
		return {entryRead : null, inScope: false, typeOfEntry : "unknown"};
	}

	if (filterOnGroups || filterOnAttributes) {
		entry = sourceLDAP.findEntry("$dn", sourceDN);
		if (entry === null) {
			return {entryRead : entry, inScope: false, typeOfEntry : "unknown"};
		}

		var oc = entry.getAttribute("objectClass")
		var typeOfEntry = entryType(oc)

		if (filterOnGroups
			&& "person".equals(typeOfEntry)
			&& !groupFiltersSatisfied(sourceLDAP, sourceDN, changeDetType, entry)) {
			return {entryRead : entry, inScope: false, typeOfEntry : typeOfEntry};
		}

		if (filterOnAttributes
			&& "person".equals(typeOfEntry)
			&& !attributeFiltersSatisfied(entry)) {
			return {entryRead : entry, inScope: false, typeOfEntry : typeOfEntry};
		}
	}	

	return {entryRead : entry, inScope: true, typeOfEntry : typeOfEntry};
}	

var groupFilterErrorMsg = resource.getString("LDAPSYNC.ERROR.FOR.GROUP.FILTER");
function groupFiltersSatisfied(sourceLDAP, dn, ldapType, entry) {
	if (!filterOnGroups) {
		return true;
	}	

	var foundIt = false;

	if ("AD".equalsIgnoreCase(ldapType)) {
		var membership = entry.getAttribute("memberOf"); // for AD
		if (membership !== null && groupFilters != null) {
			for (var i = groupFilters.length-1; i >= 0 && !foundIt; i--) {
				var thisFilter = groupFilters[i];

				for (var j = membership.size()-1; j >= 0 && !foundIt; j--) {
					foundIt = membership.getValue(j).equalsIgnoreCase(thisFilter);
				}	
//				match = membership.hasValue(groupFilters[i]);				
				if (deBug) logmsg("groupFilterSatisfied(AD) - checking for " + dn + " in " + thisFilter + "  found it: " + foundIt);
			}

//			if (deBug) logmsg("groupFilterSatisfied - checking for " + dn + " in " + groupFilters[i] + "  found it: " + match);
		}

	} else	
	if (sourceLDAP !== null 
		&& sourceLDAP instanceof com.ibm.di.connector.LDAPConnector 
		&& groupFilters != null) {
		for (var i = 0; i < groupFilters.length && !foundIt; i++) {
			var match = false;
			try {
				try {
					match = sourceLDAP.compare(groupFilters[i], "uniquemember", dn);
				} catch (ex) {
					// do nothing
				}

				if (!match) {
					try {
						match = sourceLDAP.compare(groupFilters[i], "member", dn);
					} catch (ex) {
						// do nothing
					}		
				}	
			} catch (ex) {
				logmsg("WARN", groupFilterErrorMsg + ": " + groupFilters[i] + " - " + ex);
				addToStats(flowKey, "warn", "warn");
				match = false;
			}

			if (deBug) logmsg("groupFilterSatisfied - checking for " + dn + " in " + groupFilters[i] + "  found it: " + match);
			foundIt = match;
		}
	}

	return foundIt;
}

function attributeFiltersSatisfied(entry) {
	if (!filterOnAttributes) {
		return true;
	}

	var ok = false;

	if (entry === null) {
		return ok;
	}

	for (var i = 0; i < attributeFilters.length; i++) {
		var filter = attributeFilters[i];
		ok = filterMatched(filter, entry);
		if (deBug) logmsg("--> attributeFiltersSatisfied - " + filter.name + " " + filter.operator + " " + filter.value + "  => " + ok);

		if (ok == filterAttributesOR) {
			break;
		}	
	}	

	return ok;
}		

function filterMatched(filter, entry) {
	var satisisfied = false;
	var att = entry.getAttribute(filter.name);
	var attValue = null;
	var fltr = filter.value;

	i = 0;

	do {
		if (att != null) {
			attValue = att.getValue(i);
		}		

		if (attValue !== null) {
			attValue = attValue.toString().toLowerCase().trim();
		}

		switch (filter.operator.toLowerCase()) {
			case "equals": satisfied = attValue !== null && fltr.equals(attValue);
				break;
			case "contains": satisfied = attValue !== null && attValue.indexOf(fltr) >= 0;
				break;
			case "startswith": satisfied = attValue !== null && attValue.startsWith(fltr);
				break;
			case "endswith": satisfied = attValue !== null && attValue.endsWith(fltr);
				break;
			case "hasvalue": satisfied = attValue !== null;
				break;
			case "not_equals": satisfied = attValue === null || !fltr.equals(attValue);
				break;
			case "not_contains": satisfied = attValue === null || attValue.indexOf(fltr) < 0;
				break;
			case "not_startswith": satisfied = attValue === null || !attValue.startsWith(fltr);
				break;
			case "not_endswith": satisfied = attValue === null || !attValue.endsWith(fltr);
				break;
			case "not_hasvalue": satisfied = attValue === null;
				break;
			default: satisfied = false;
		}

		i++;
	} while (!satisfied && att != null && i < att.size());

	return satisfied;
}	

function determineTarget() {
	var alName = getProperty("target.endpoint.al");

	targetIsTDS = false;
	targetIsLDAP = false;

	if (!cloudSync) {
		var targetIsLDAPProp = getProperty("target.isLDAP", false);
		var targetIsTDSProp = getProperty("target.isTDS", false);

		if (targetIsTDSProp === null) {
			targetIsTDSProp = getProperty("target.isSDS", false);
		}

		targetIsTDS = ("true".equals(targetIsTDSProp));

		if (targetIsTDS) {
			targetIsLDAP = true;
		} else {
			targetIsLDAP = ("true".equalsIgnoreCase(targetIsLDAPProp));
		}	
	}	

	if (alName === null) {
		var ctrName = getProperty("target.endpoint.connector.name", "TargetTDS");
		var ctr = null;
		if (ctrName !== null)  {
			ctr = system.getConnector(ctrName);
		}	
	}
}

function jsonStr(e) {
	var str = ""
	var out = new java.io.StringWriter()
	try {    
		var parser = system.getParser("ibmdi.JSONParser")
		parser.setOutputStream(out)
		parser.initParser()
		parser.writeEntry(e)
		str = out.toString()
	} catch (ex) {
		str = work.toString()
	}

	return str
}

var jsonReportEntry = system.newEntry()
var entryTypes = ["container","person","group"]
var statTypes = ["processed","add","modify","delete","unchanged","skipped","error","warning"]
function jsonReport(flowKey, typeOfEntry) {
	var jre = jsonReportEntry;

	if (jre.status == null) {	
		jre.status = null
		jre.status.total = null
//		jre.flowReport = FlowReport()
	}	

	jre.status.total.processed = getStats(flowKey, "total","processed")
	jre.status.total.warning = getStats(flowKey, "warning","warning")
	jre.status.total.error = getStats(flowKey, "error","error")
	for (var et in entryTypes) {
		et = entryTypes[et]
		jre.status[et] = null
		for (var st in statTypes) {
			st = statTypes[st]
			jre.status[et][st] = getStats(flowKey, et, st)
		}
	}

	if (typeof(typeOfEntry) != "undefined") {
		jre.typeOfEntry = typeOfEntry
	}	

	if (simulate) {
		jre.type = "simulate"
	} else
	if (typeof isSync !== "undefined" && isSync) {
		jre.type = "sync"
	} else {
		jre.type = "migrate"
	}			

	return jre.toJSON()
}

var minimumMessageInterval = 1500;
var lastMessageSent = 0;
var messageBurstSize = 10;
var messageBurst = messageBurstSize;
var renewBurstInterval = minimumMessageInterval*3;
function updateProgressReport(flowKey, typeOfEntry, forceSend) {
	var now = new java.util.Date().getTime()
	var diff = now - lastMessageSent;

	if (typeof(forceSend) == "undefined") {
		forceSend = false
	}	

	if (typeof(typeOfEntry) == "undefined" || typeOfEntry == null || typeOfEntry == "") {
		typeOfEntry = "* unknown *"
	}

	if (forceSend || diff > minimumMessageInterval || messageBurst > 0) {
		var jsonRepStr = jsonReport(flowKey, typeOfEntry)
		if (deBug) logmsg("\n---@@@---> jsonReport: " + jsonRepStr)
		task.logmonitor(jsonRepStr)
		if (!forceSend) {
			lastMessageSent = now;
		}	
		task.setTombstoneUserMessage(jsonRepStr);

		if (diff > renewBurstInterval) {
			messageBurst = messageBurstSize;
		} else {
			messageBurst = messageBurst - 1;
		}	
	}	
}

var lostFile = null
var firstLostEntry = true
function writeLostEntry(entry, lostFileName, errorMsg) {
	var logFilepath
	var file
	var filename
	var lm
	var logFileFullname
	if (lostFile == null) {
		// create file
		filename = flowKey + "_" + lostFileName;
		logFileFullname = logDirectory + "/" + filename + ".ldif.temp"
		lostFile = system.getConnector("Connectors/ChangesLost")
		lostFile.setParam("filePath", logFileFullname)
		logFiles.setAttribute(logFileFullname,lostFile)

		try {
			file = openOutputFile(logFileFullname)
			file.close()
			lostFile.initialize(null)
		} catch (ex) {
			msg = resource.getString("LDAPSYNC.ERROR.OPENING.FILE") 
					+ "(" + lostFileName + "): " + logFileFullname + " - " + ex
			logmsg("ERROR", msg)
			throw where() + " - " + msg
		}
	}

	if (entry != null && lostFile != null && typeof(filename) != "undefined") {
		if (firstLostEntry) {
			firstLostEntry = false

			logmsg("WARN",resource.getString("LDAPSYNC.ANY.ENTRIES.THAT.WERE.NOT.WRITTEN.TO.THE.TARGET.CAN.BE.FOUND.HERE") 
					+ " : " + logFileFullname);
		}	

		lostFile.putEntry(entry)
		logmsg(resource.getString("LDAPSYNC.SOURCE.ENTRY.NOT.WRITTEN.TO.TARGET") + ": " + work.getString("$dn"))
	}

	if (entry != null && errorMsg != null && errorMsg.indexOf("CTGDIS1984I") < 0) {
		var retryError = null;
		if (lastException != null && lastException.get("latest") != null) {
			retryError = lastException.get("latest").toString();
		}	
		if (retryError == null && error != null) {
			retryError = error.getString("exception");
		}	

		retryList.add({	dn: entry.getString("$dn"),
						error: retryError,
						operation: entry.getOperation(),
						entry: entry });
	} 
}

function setFlowKey(fk) {
	flowKey = fk;
}

var activities = ["person","group","container"]
function activity(migrate) {
	var act = ""
	var adds = 0
	var mods = 0
	var deletes = 0
	var unchanged = 0
	var errors = 0
	var warnings = 0
	var totals = 0
	var type = "sync"
	for (var i = 0; i < activities.length; i++) {
		adds = getStats(flowKey, activities[i], "add")
		mods = getStats(flowKey, activities[i], "modify")
		deletes = getStats(flowKey, activities[i], "delete")
		unchanged = getStats(flowKey, activities[i], "unchanged")

/* removed 14.4.15 - this will be done in the UI instead		
		if (migrate) {
			adds += (mods + deletes + unchanged);
			mods = 0;
			deletes = 0;
			unchanged = 0;
		}	
*/		
		totals += adds + mods + deletes	
		act += "," + adds + "," + mods + "," + deletes + "," + unchanged
	}

	if (simulate) {
		type = "simulate"		
	} else	
	if (migrate) {
		type = "migrate"
	}

	errors = getStats(flowKey, "error", "error")
	warnings = getStats(flowKey, "warn", "warn")

	act += "," + errors + "," + warnings

	totals += errors + warnings

	return (new java.util.Date()).getTime() + act + "," + type + "," + syncAborted;
}

function flowTotals() {
	var totals = 0
	for (var i = 0; i < activities.length; i++) {
		totals += getStats(flowKey, activities[i], "add")
		totals += getStats(flowKey, activities[i], "modify")
		totals += getStats(flowKey, activities[i], "delete")
		totals += getStats(flowKey, activities[i], "error")
		totals += getStats(flowKey, activities[i], "skip")
		totals += getStats(flowKey, activities[i], "warn")
	}

	totals += getStats(flowKey, "error", "error")
	totals += getStats(flowKey, "warn", "warn")
	totals += getStats(flowKey, "skip", "skip")

	return totals
}

actHeaders = "date,useradd,usermod,userdel,userunchanged,groupadd,groupmod,groupdel,groupunchanged,containeradd,containermod,containerdel,containerunchanged,errors,warnings,type,aborted"
function logActivity(migrate) {
	if (simulate) {
		// do nothing
		return;
	}	
	var act = activity(migrate)
	var oldActivity = new java.lang.StringBuffer()
	var file
	var newLine
	var lastLine
	var i
	var actParts = system.splitString(actHeaders, ",")

	// First read old Activity log for this flow. If last line is all zeros, then
	// replace it with the current activity info. If it is not all zeros, then append the new
	// info
	try {
		file = system.openFileForInput(logDirectory + "/" + flowKey + "_Activity.log")
		do {
			newLine = file.readLine()
			if (newLine != null) {
				lastLine = newLine
				oldActivity.append(newLine + "\n")
			}	
		} while (newLine != null)
	} catch (ex) {
		lastLine = "0,0,0,0" // dummy All Zeros line
	}		

	try {
		file.close()
	} catch (ex) {
		// do nothing
	}		

	var parts = system.splitString(lastLine,",")
	var lastTotal = 0
	for (i = 1; i < (parts.length-1); i++) {
		if (system.isValidInt(parts[i])) {
			lastTotal += system.toInt(parts[i])
		}	
	}	

	var file = openOutputFile(logDirectory + "/" + flowKey + "_Activity.log")
	file.write(actHeaders)
	file.newLine()

	// for Incremental Sync (not migrate) then write the old activity info, except the last all zeros line
	if (!migrate) {
		parts = system.splitString(oldActivity.toString(),"\n")
		for (i = 1; i < (parts.length-1); i++) {
			file.write(parts[i])
			file.newLine()
		}

		if (lastTotal > 0 && parts.length > 1) {
			file.write(parts[parts.length-1])
			file.newLine()
		}	
	}	

	file.write(act)
	file.newLine()
	file.close()
}

function stackTrace(ex) {
	var sw
	var pw

	if (ex == null) {
		return ""
	}	

	try {
		sw = java.io.StringWriter();
		pw = java.io.PrintWriter(sw);
		ex.printStackTrace(pw);
		pw.close();
	} catch (ex2) {
		var sw = ex
	}	

	return sw
}	

function defaultErrorHandling(errorType, add2stats, writeback) {
	if (typeof(add2stats) == "undefined") { add2stats = true } 
	if (typeof(writeback) == "undefined") { writeback = false }	

	var eclass = error.getString("class")
	if (eclass != null && eclass.endsWith("ExitBranchException")) {
		return;
	}

	var sourceDN = work.getString("$dn");
	if (alTCB.getObject("$errorLogged") == sourceDN || work.getObject("$errorLogged") == sourceDN) {
		add2stats = false;

		alTCB["$errorLogged"] = sourceDN;
		work["$errorLogged"] = sourceDN;
	}	

	var errorMsg = ""
	var cname = thisConnector.getName().toLowerCase();
	var isSource = cname.indexOf("source") >= 0;
	var fixMsg = correctionMsg(false, isSource, thisConnector, error)

	var ex = error.getObject("exception");
	var sw = ""
	if (ex != null) {
		setException(ex, "writeError")
		sw = stackTrace(ex)
	}

	if (fixMsg.length > 0) {
		logmsg(errorType.toUpperCase(), fixMsg)
		fixMsg = "\n" + fixMsg
	}

	errorMsg = "";
	if (typeof error !== "undefined" && error.status != "ok") {
		errorMsg = error.message + " (" + error.operation + ") " + error.exception;
	}

	errorMsg = resource.getString("LDAPSYNC.ERROR.DURING.OPERATION") + " -> "
					+ errorMsg + fixMsg

	var stmsg = resource.getString("LDAPSYNC.STACKTRACE");

	failed.put(cname, errorMsg + "\n" + stmsg + ":\n" + sw);

	if (add2stats) {
		logmsg(errorType.toUpperCase(), errorMsg + "\n" + stmsg + ":\n" + sw);

		if (typeof(typeOfEntry) != "undefined") {
			addToStats(flowKey, typeOfEntry, errorType.toLowerCase());
		} else {
			addToStats(flowKey, errorType.toLowerCase(), errorType.toLowerCase());
		}	
	}	

	// to pass info back to calling ALs	
	alTCB.error = error;
}

function defaultInitErrorHandling(errorType, add2stats, writeback) {
	if (typeof(add2stats) == "undefined") {
		add2stats = false;
	}	

	if (typeof(writeback) == "undefined") {
		writeback = false
	}	

	var eclass = error.getString("class")
	if (eclass != null && eclass.endsWith("ExitBranchException")) {
		return
	}

	logmsg(errorType.toUpperCase(), where() + " - " + error.exception + " - " + error.message)

	var cname = thisConnector.getName().toLowerCase();
	var isSource = cname.indexOf("source") >= 0;

	try {
		var ldap = thisConnector.connector;
		if (ldap instanceof com.ibm.di.connector.LDAPConnector && getProperty("source.ldap.pageSize") != null) {
			ldap.setParam("ldapPageSize", null);
			ldap.initialize(null);
			return; // continue as if nothing has happened
		}	
	} catch (ex) {
		// continue with the current error
	}

	var fixMsg = correctionMsg(false, isSource, thisConnector, error)
	if (fixMsg.length > 0) {
		logmsg(errorType.toUpperCase(), fixMsg)
		fixMsg = "\n" + fixMsg
	}	

	var msg = resource.getString("LDAPSYNC.ERROR.DURING.INITIALIZATION")
	failed.put(flowKey + "_" + thisConnector.getName(), msg + ": " + error.exception + " / " + error.message + fixMsg)

	if (add2stats) {
		addToStats(flowKey, errorType.toLowerCase(), errorType.toLowerCase());
	}	

	thisConnector.connector.setParam("initWentOk", "false")

	var ex = error.getObject("exception");
	var sw = ""
	if (ex != null) {
		setException(ex, "connectionError")

		if (errorType.equalsIgnoreCase("ERROR") || errorType.equalsIgnoreCase("FATAL")) {
			setException(ex, "fatal")
		}	

		sw = stackTrace(ex)
	}
	var stmsg = resource.getString("LDAPSYNC.STACKTRACE")
	logmsg("FATAL",msg + ": " + error.exception + " / " + error.message + fixMsg + "\n" + stmsg + ":\n" + sw)
//	task.shutdown();
	throw (where() + " - " + msg + ": " + error.exception + " / " + error.message + fixMsg)
	//throw (where() + " - " + msg + ": " + error.exception + " / " + error.message + fixMsg + "\n" + stmsg + ":\n" + sw)}
}

function endOfFlowHandling(isSync) {
    var ex = getException("fatal");

	if (doTiming && timingMap != null) {
		timing("end")

		timingMap.remove("timingEntry")

		try {
			if (timingFile != null) {
				timingFile.close()
			}

			timingFile = openOutputFile(logDirectory + "/0_Timing_" + flowKey + "_totals.log")
			var keys = timingMap.keySet().toArray()
//			java.util.Arrays.sort(keys)

			var totalTime = 0
			var sortMap = new java.util.concurrent.ConcurrentHashMap()
			var thisVal
			var thisKey
			var e
			for (var key in keys) {
				thisVal = timingMap.get(key)
				totalTime = totalTime + thisVal
				e = system.newEntry()
				e.timingVal = thisVal
				e.keyVal = key
				var valStr = rjfill(thisVal,10,"0")
				sortMap.put(valStr, e)
			}

			keys = sortMap.keySet().toArray()
			java.util.Arrays.sort(keys)

			for (var key in keys) {
				e = sortMap.get(key)
				thisVal = e.getObject("timingVal")
				thisKey = e.getObject("keyVal")
				timingFile.write(thisKey + ";" + Math.round(thisVal) + ";" + Math.round(thisVal/totalTime*10000)/100)
				timingFile.newLine()
			}
			timingFile.write("total time;" + Math.round(totalTime)+";100")
			timingFile.newLine()

			timingFile.close()

		} catch (ex) {
			// do nothing
		}

		invokeHook("epilogend", work);
	}

//	updateProgressReport(flowKey, entryType, true);

	if (ex == null) {
		ex = getException("error")
	}

	if (ex == null) {
		ex = error.getObject("exception")
	}

	if (ex != null && String(ex).toLowerCase().indexOf("interrupt") < 0) {
		setException(ex, "runDataFlow")
		if (work.getObject("$errorLogged") == null && alTCB.getObject("$errorLogged") == null) {
			addToStats(flowKey, "error", "error");
			logmsg("ERROR", where() + " - " + ex);
		}	
		task.getStats().exception(new java.lang.Exception(ex))	
	}

	updateProgressReport(flowKey, null, true)

	logActivity(!isSync)

	if (typeof(flowKey) != "undefined" && flowKey != null && flowKey.length > 0) {
		logReport(flowKey)
	}

	try {
		if (typeof(readALFC) != "undefined") {
			readALFC.terminate()
		}
	} catch (ex) {
		// do nothing
	}

	if (typeof(joinALFC) != "undefined") {
		itr = joinALFC.keySet().iterator()

		while (itr.hasNext()) {
			try {
				var nxt = itr.next()
				joinALFC.get(nxt).terminate()
			} catch (ex) {
				// do nothing
			}
		}
	}	

	try {		
		closeAllHooks();
	} catch (ex) {
		// do nothing
	}

	rollLogs()

	if (typeof(readError) != "undefined" && readError.length > 0) {
		throw readError
	}
}


// for testConnection and ReadEntries ALs
function testConnection() {
	var jsonEntry = system.newEntry()
	var sysInfo = detectForm();
	var form = sysInfo.form;
	var readEntry = null
	var id = opEntry.getString("testId")
	var searchFilter = "(objectClass="+getProperty("source.userObjectClass","person")+")";
	var sourceDN;
	var changeDetType = getProperty("source.changeDetectionType","delta");
	var baseurl = null;

	if (cloudSync) {
		searchFilter = "(objectClass=person)";
	}

	if (cloudSync) {
		searchFilter = "(|" + searchFilter + "(objectClass=user)(objectClass=person))";
	}

	jsonEntry.enableDOM()
	jsonEntry.operation = "initialization"
	jsonEntry.form = form
	jsonEntry.sys_vendor = sysInfo.vendor;
	jsonEntry.sys_version = sysInfo.version;
	jsonEntry.form = sysInfo.form;
	jsonEntry.endpoint = opEntry.getString("endpoint.name")
	jsonEntry.status = "success" // optimistic, me :)

	var typeOfEntry = opEntry.getString("read.type")
	if (typeOfEntry == null || !("person".equals(typeOfEntry) || "group".equals(typeOfEntry))) {
		typeOfEntry = "person"
	}

	typeOfEntry = typeOfEntry.trim().toLowerCase()
	if (typeOfEntry.endsWith("s")) {
		typeOfEntry = typeOfEntry.substring(0, typeOfEntry.length-1)
	}

	if ("group".equals(typeOfEntry)) {
		searchFilter = "(objectClass="+getProperty("source.groupObjectClass")+")"
	}

	var returnTotal = "true".equalsIgnoreCase(getProperty("read.returnTotal", "false"));
	var totalEntries = 0;
	var start = getIntProperty("read.start", "0")
	var count = getIntProperty("read.count", "1")

	switch (form) {
		case "Form_LDAP" :
		case "Form_AD" :
		case "Form_SUN" :
		case "Form_TDS" : 		opEntry["source.connector.name"] = "Connectors/SourceLDAP"
								break
		case "Form_Custom AL" : opEntry["source.connector.name"] = "ALFC"
								break
		case "Form_JDBC" :		opEntry["source.connector.name"] = "ibmdi.JDBC"
								break
		case "Form_File" : 		opEntry["source.connector.name"] = "ibmdi.FileSystem"
								break
	}

	var connectorName = opEntry.getString("source.connector.name")
	var gotErrors = ""
	var init = true
	if ("ALFC".equals(connectorName)) {
		var readALFC = system.getFunction("ibmdi.AssemblyLineFC")

		var noALsFound = true

		var AL = "source.read." + typeOfEntry + ".AL"
		var alName = getALName(AL)
		if (alName == null || alName.trim().length == 0) {
			jsonEntry.status = "failed"
			jsonEntry.exception = resource.getString("LDAPSYNC.ASSEMBLYLINE.NAME.NOT.SPECIFIED")
			jsonEntry.message = jsonEntry.exception
			return jsonEntry
		}

		readALFC.setParam("assemblyLine", alName)
		readALFC.setParam("shareLog", "true")
		readALFC.setParam("mode", "2") // Manual mode

		try {
			init = true
			var tcb = readALFC.getTCB();
			passGlobalVariablesViaTCB(tcb);
			opEntry["$typeOfEntry"] = typeOfEntry;
			tcb.setOperationInitParams(opEntry);
			tcb.setTaskName(flowKey + "_" + alName + "_Test_" + typeOfEntry);

			readALFC.initialize(null)

			init = false
			jsonEntry.operation = "read"
			readEntry = "none"
			if (count > 0) {
				for (; start > 0 && readEntry != null;) {
					readEntry = readALFC.perform(null)
//					if (readEntry !== null && attributeFiltersSatisfied(readEntry)) {
					if (readEntry !== null) {
						start--;
						totalEntries++;
					}
				}
				for (; count > 0 && readEntry != null;) {
					readEntry = readALFC.perform(null)
//					if (readEntry != null && attributeFiltersSatisfied(readEntry)) {
					if (readEntry != null) {
						jsonEntry.addAttributeValue("entries", simplifyAttributes(readEntry));
						count--;
						totalEntries++;
					}	
				}
			}	

			if (returnTotal) {
				do {
					readEntry = readALFC.perform(null);
//					if (readEntry !== null && attributeFiltersSatisfied(readEntry)) {
					if (readEntry !== null) {
						totalEntries++;
					}
				} while (readEntry !== null);
			}

			readALFC.terminate()
		} catch (ex) {
			try {
				readALFC.terminate()
			} catch (ex2) {
				// ignore
			}
			jsonEntry.status = "failed";
			jsonEntry.exception = stackTrace(ex);
			jsonEntry.message = userFriendlyMsg(ex.toString());
			return jsonEntry
		}
	} else {
		try {
			init = true
			ctr = configureConnector(true, false)

			if (ctr != null && ctr.selectEntries != null) {

				var searchBase = getProperty("source.ldap.searchBase") || ""
				var contexts = system.newAttribute("contexts")

				// if this is LDAP and searchBase is not set, throw an error unless it's a contexts request (count == 0)
				if (ctr instanceof com.ibm.di.connector.LDAPConnector) {
					var srchBase = (ctr.getParam("ldapSearchBase") || "").trim();
					baseurl = ctr.getParam("ldapUrl");
					if (srchBase.length == 0 && count > 0) {
						var errorMsg = resource.getString("LDAPSYNC.ERROR.DURING.INITIALIZATION") + " - "
										+ resource.getString("LDAPSYNC.PROPERTY.NOT.SPECIFIED") + ": ";
						if (!id.endsWith("GeneralSettings")) {
							throw errorMsg + resource.getString("LDAPSYNC.SEARCH.BASE") 
						} else {
							throw errorMsg + resource.getString("LDAPSYNC.DEFAULT.TARGET.CONTAINER")
						} 
					}

					// return contexts
					jsonEntry.changelog = false;

					jsonEntry.ldapType = detectLdapType(form);

					try {
						var ctx = ctr.getLdapContext()
						var attNames = ['namingcontexts']
						var attrs = ctx.getAttributes("", attNames)
						var bases = attrs.get(attNames[0])
						if (bases != null) {
							for (var ndx = 0; ndx < bases.size(); ndx++) {
								contexts.addValue(bases.get(ndx));
								baseSuffix = bases.get(ndx);
								if ("CN=Changelog".equalsIgnoreCase(baseSuffix)
									&& (   "Sun".equalsIgnoreCase(jsonEntry.ldapType) 
										|| "SDS".equalsIgnoreCase(jsonEntry.ldapType))) {
									jsonEntry.changelog = true;
								} else 
								if ("AD".equalsIgnoreCase(jsonEntry.ldapType)) {
									try {
										// create LdapName and get Rdns
										baseDN = new javax.naming.ldap.LdapName(baseSuffix);
										rdns = baseDN.getRdns();

										// Go through all rdns to look for CN=Deleted Objects
										for (rdnNdx = rdns.size()-1; rdnNdx >= 0 && !jsonEntry.changelog; rdnNdx--) {
											thisRDN = rdns.get(rdnNdx);
											if ("Deleted Objects".equalsIgnoreCase(thisRDN.getValue())
												&& "CN".equalsIgnoreCase(thisRDN.getType())) {
												jsonEntry.changelog = true;
											}
										}
									} catch (exRdn) {
										jsonEntry.changelog = false;
									}
								}	
							}
						}

						if ( ("Sun".equalsIgnoreCase(jsonEntry.ldapType) 
							  || "SDS".equalsIgnoreCase(jsonEntry.ldapType))
							&& !("true".equals(jsonEntry.changelog))) {
							jsonEntry.message = resource.getString("LDAPSYNC.NOTE.MAKE.SURE.THE.CHANGELOG.FEATURE.IS.ENABLED.FOR.THE.SOURCE.DIRECTORY.SERVER");
						} else
						if ("AD".equalsIgnoreCase(jsonEntry.ldapType)
							&& !("true".equals(jsonEntry.changelog))) {
							jsonEntry.message = resource.getString("LDAPSYNC.NOTE.MAKE.SURE.DELETED.OBJECTS.CAN.BE.READ.IN.THE.SOURCE.ACTIVE.DIRECTORY");		
						}

						jsonEntry.setAttribute(contexts)
					} catch (ex2) {
						// 
					}	
				}

/* moved this test up to where contexts are read
				// if this is a test of the Central SDS, then look for CN=Changelog as well
				if (id.endsWith("GeneralSettings")) {
					readEntry = ctr.findEntry("$dn","CN=Changelog");				
					if (readEntry == null) {
						throw resource.getString("LDAPSYNC.CHANGELOG.NOT.ENABLED")
					}
				} 
*/
				// test selectEntries call				
				jsonEntry.operation = "selection"
				ctr.setParam("ldapSearchFilter", searchFilter)
				ctr.selectEntries()

				// if start or count are > 0 then this is NOT a call to return Contexts
				if (count > 0) { 
					init = false
					jsonEntry.operation = "read"
					readEntry = "none"
					for (; start > 0 && readEntry != null;) {
						readEntry = ctr.getNextEntry()
						if (readEntry !== null) {
/* removed 20150421 when we made List Users use simulated initial sync							
							sourceDN = cleanDN(work.getString("$dn"));
							if (attributeFiltersSatisfied(readEntry)
								&& groupFiltersSatisfied(ctr, sourceDN, changeDetType, readEntry)) {
								start--;
								totalEntries++;
							}	
*/							
							start--;
							totalEntries++;
						}
					}
					for (; count > 0 && readEntry != null;) {
						readEntry = ctr.getNextEntry();
						if (readEntry !== null) {
/* removed 20150421 when we made List Users use simulated initial sync							
							sourceDN = cleanDN(work.getString("$dn"));
							if (attributeFiltersSatisfied(readEntry)
								&& groupFiltersSatisfied(ctr, sourceDN, changeDetType, readEntry)) {
								jsonEntry.addAttributeValue("entries", simplifyAttributes(readEntry))
								count--;
								totalEntries++;
							}	
*/							
							jsonEntry.addAttributeValue("entries", simplifyAttributes(readEntry))
							count--;
							totalEntries++;
						}
					}	
				}	
				if (returnTotal) {
					do {
						init = false
						jsonEntry.operation = "read and count"
						readEntry = ctr.getNextEntry();
						if (readEntry !== null) {
/* removed 20150421 when we made List Users use simulated initial sync							
							sourceDN = cleanDN(work.getString("$dn"));
 * 							if (attributeFiltersSatisfied(readEntry)
								&& groupFiltersSatisfied(ctr, sourceDN, changeDetType, readEntry)) {
								totalEntries++;
							}	
*/							
							totalEntries++;
						}
					} while (readEntry !== null);
				} 
			}
		} catch (ex) {
			jsonEntry.exception = stackTrace(ex)
			jsonEntry.message = userFriendlyMsg(ex.toString(), baseurl);
			jsonEntry.status = "failed"
			return jsonEntry
		}

	}

	jsonEntry.operation = "test complete";
	if (returnTotal) {
		jsonEntry.totalEntries = totalEntries;
	}

	return jsonEntry
}

function detectForm() {
	var form = {};

	if (getProperty("source.ldap.searchbase") != null) {
		var ldap = system.getConnector("ibmdi.LDAP");
		ldap.setParam("ldapUrl", getProperty("source.ldap.url"));
		ldap.setParam("ldapUsername", getProperty("source.ldap.user"));
		ldap.setParam("ldapPassword", getProperty("source.ldap.password"));
		ldap.setParam("ldapSearchBase", getProperty("source.ldap.searchbase"));

		try {
			ldap.initialize(null);
			var serverInfo = ldap.getServerInfo();
			ldap.terminate();

			if (serverInfo.size() <= 1) {
				ldap.setParam("ldapReturnAttributes", "*\n+");
				ldap.initialize(null);
				serverInfo = ldap.findEntry("$dn","");
				ldap.terminate();
			}

			form = returnForm(serverInfo);
		} catch (ex) {
			form.form = getProperty("source.form");
			form.type = detectLdapType(form.form);
			if (form == null) {
				throw resource.getString("LDAPSYNC.ERROR.DURING.INITIALIZATION");
			}	
		}
	} else {
		form.form = getProperty("source.form");
		form.type = detectLdapType(form.form);
		if (form == null) {
			throw resource.getString("LDAPSYNC.ERROR.DURING.INITIALIZATION");
		}	
	}	

	return form;
}

function returnForm(e) {
	var vName = e.getString("vendorName");
	var vVers = e.getString("vendorVersion");
	var fFunc = e.getString("forestFunctionality");
	var orcl = e.getString("orcldirectoryversion");
	var orclVrs = e.getString("orcldirectoryversion");
	var oc = e.getAttribute("objectClass");
	var supportedLDAP = e.getString("supportedLDAPVersion");

	var ret = {};

	if (oc !== null) {
		for (var v in oc) {
			if (v.equalsIgnoreCase("OpenLDAProotDSE")) {
				vName = "OpenLDAP";
				break;
			}
		}
	}	

	if (orcl !== null) {
		vName = "Oracle Corporation";
		vVers = orcl;
	} else
	if (fFunc !== null) {
		vName = "Microsoft";
		vVers = "Active Directory";
	}

	if (vName === null) {
		vName = "*Unknown vendor*"
	}

	if (orclVrs !== null) {
		vVers = orclVers;
	} else
	if (vVers === null) {
		vVers = "*Unknown version*"
	}

	var vn = vName.toLowerCase().trim();
	if (vn.indexOf("international business machines") >= 0) {
		setChangeDetection("sds");
		ret.form = "Form_TDS";
	} else
	if (vn.indexOf("microsoft") >= 0) {
		setChangeDetection("ad");
		ret.form = "Form_AD";
	} else
	if (vn.indexOf("sun micro") >= 0) {
		setChangeDetection("sun");
		ret.form = "Form_SUN";
	} else {
		setChangeDetection("delta");
		ret.form = "Form_LDAP";
	}

	ret.vendor = vName;
	ret.version = vVers;

	return ret;
}

function setChangeDetection(cdcType) {
	opEntry[flowKey + "source.changeDetectionType"] = cdcType;
}

function detectLdapType(form) {
	switch (form) {
		case "Form_AD" : return "AD";
		case "Form_SUN" : return "Sun";
		case "Form_TDS" : return "SDS";
		default : return "unknown";
	}
}

function configureConnector(doInit, doSelect, propPrefix, ctrName) {
	if (typeof(doInit) == "undefined") { doInit = true }
	if (typeof(doSelect) == "undefined") { doSelect = true }
	if (typeof(propPrefix) == "undefined" || propPrefix == null) { propPrefix = "source" }
	if (typeof(ctrName) == "undefined" || ctrName === null) { ctrName = getProperty(propPrefix + ".connector.name"); }	
	if (typeof(useCtr) != "undefined") {
		var ctr = useCtr;
	} else {
		var ctr = system.getConnector(ctrName)
	}

	if (ctr == null) {
		var errormsg = resource.getString("LDAPSYNC.CONNECTOR.NOT.FOUND") + ": " + ctrName + "(" + propPrefix + ".connector.name)"
		throw errormsg
	}

	setParameters(ctr,"connector")

	parserName = getProperty(propPrefix + ".parser.name")
	if (parserName != null && !parserName.startsWith("[")) {
		parser = system.getParser(parserName)
		if (parser == null) {
			var errormsg = resource.getString("LDAPSYNC.PARSER.NOT.FOUND") + ": " + parserName
			throw errormsg
		}

		setParameters(parser,"parser")
		ctr.setParser(parser)
	}

	if (doInit || doSelect) {
		try {
			ctr.terminate()
		} catch (ex) {
			// do nothing
		}
	}	

	if (doInit || doSelect) {	
		try {
			ctr.initialize(null)
		} catch (ex) {
			setException(ex, "fatal")
			throw where() + "- initialize(null) - " + ex
		}	
	}	

	if (doSelect) {
		try {
			ctr.selectEntries()
		} catch (ex) {
			setException(ex, "fatal")
			throw where() + "- selectEntries() - " + ex
		}	
	}

	return ctr
}

function setParameters(obj, type) {
	var paramNames = opEntry.getAttributeNames()
	var paramPrefix = "source." + type.toLowerCase() + ".parameter."
	for (var pname in paramNames) {
		var p = pname.indexOf(paramPrefix)
		if (p >= 0) {
			var paramValue = getProperty(pname)
			var param = pname.substring(p + paramPrefix.length)
			obj.setParam(param, paramValue)
		}	
	}
}

function isSimulation() {
	/*
	var simulate = getProperty("simulate")
	if (simulate == null)
		simulate = "true"
	var simulateBool = !"false".equalsIgnoreCase(simulate)
	return simulateBool
	*/
	return getBooleanProperty("simulate", false);
}

function notifyWritebackError(error, fromWhere) {
	if (typeof(fromWhere) == "undefined") {
		fromWhere = "WritebackMain"
	}

	var eclass = error.getString("class")
	if (eclass != null && eclass.endsWith("ExitBranchException")) {
		return
	}

	var jsonEntry = system.newEntry()
	jsonEntry.timestamp = new java.util.Date().getTime()
	jsonEntry.al = task.getShortName()
	jsonEntry.status = "failed"
	if (error && error != null) {
		jsonEntry.merge(error)
	}	
	jsonEntry.enableDOM()

	json = jsonEntry.toJSON()

	sendCustomNotification("fds.writeback", fromWhere, json);	
}


function simplifyAttributes(simEntry) {
	if (simEntry == null || simEntry.size() == 0) {
		return null
	}

	var attNames = simEntry.getAttributeNames()

	for (var i = attNames.length-1; i--;) {
		var attName = attNames[i]
		var att = simEntry.getAttribute(attName)
		if (att.size() > 5) {
			simEntry.setAttribute(attName, "...(" + att.size() + ")...")
		} else {
			var obj = att.getValue(0)
			if (obj != null) {
				if (String(obj).startsWith("[B@")) { // if byte array
					simEntry.setAttribute(attName, "...")
				} else {
					try {
						var str = obj.toString()
						if (str.length > 80) {
							simEntry.setAttribute(attName, str.substring(0,77) + "...")
						}
					} catch (ex) {
						simEntry.setAttribute(attName, "...")
					}
				}	
			}	
		}	
	}

	return simEntry
}

function reportSimulateStatus(simEntry, endpointEntry, joinEntry, operation) {
	if (!simulate) {
		return
	}

	if ((simEntry == null || simEntry.size() == 0) && "cycling".equals(operation)) {
		return
	}

	var jsonEntry = system.newEntry()
	jsonEntry.timestamp = new java.util.Date().getTime()
	jsonEntry.flow = flowKey

	if ("starting".equals(operation) || "completed".equals(operation)) {
		jsonEntry.state = operation
	} else {
		jsonEntry.state = "cycling"
	}	

	if (typeof(operation) != "undefined") {
		jsonEntry.operation = operation
	}

	if (simEntry != null && simEntry.size() > 0) {	
		jsonEntry.entry = simEntry;
	}

	if (endpointEntry != null && endpointEntry.size() > 0) {	
		jsonEntry.source_entry = simplifyAttributes(endpointEntry);
	}

	if (joinEntry != null && joinEntry.size() > 0) {	
		jsonEntry.join_entry = simplifyAttributes(joinEntry);
	}

	jsonEntry.enableDOM()

	json = jsonEntry.toJSON()

	sendCustomNotification("fds.simulate", flowKey, json);

	if (deBug) logmsg("------- @@@ ------> Simulate State: " + json)
}

function sendCustomNotification(aType, aId, aData) {
	session.sendCustomNotification(aType, aId, aData)
}

function prepareFindEntry(work, useRDN, rdnValue) {
	var entry = null;

	if (!targetIsLDAP) {
		entry = system.newEntry();
		if (work && work != null) {
			entry.merge(work);
		}	
		entry.setAttribute(useRDN, rdnValue);
	}

	return entry;	
}

// Returns a string representation of a Javascript object
function jobj2str(jobj, lvl) {
	var strbuf = new java.lang.StringBuffer("{");
	if (typeof lvl === "undefined") { lvl = 1; } 
	for (var p in jobj) {
		strbuf.append("\n" + "                                     ".substring(0, lvl*3) + p + ": ");
		try {
			if (typeof jobj[p] === "object") {
				strbuf.append(jobj2str(jobj[p], lvl+1));
			} else {
				strbuf.append(jobj[p]);
			}
		} catch (ex) {
			if (jobj[p] != null) {
				strbuf.append(jobj[p].toString());
			}
		}
	}

	strbuf.append("\n" + "                                  ".substring(0,(lvl-1)*3) + "}");
	return strbuf.toString();
}



