if (typeof(readALFC) != "undefined" && readALFC != null) {
	readALFC.terminate()
}

if (typeof skipThisEntry !== "undefined" && skipThisEntry) {
	work["$writeStatus"] = "skipped";
	system.ignoreEntry();
}

work["$writeStatus"] = null;

try{
	var alname = task.getShortName().toLowerCase();
	var mapFile = null;
	var mapToUse = false; // output map
	var mapEverything = false;

	if (alname.indexOf("monitorqradar") >= 0 ||
		alname.indexOf("monitorsnmp") >= 0 ||
		alname.indexOf("monitorcustom") >= 0) {
		mapFile = getProperty("mapFile");
	} else {
		mapToUse = false;
		if (typeof(responseLogFile) != "undefined") {
			if(responseLogFile.toLowerCase().startsWith("writeback")) {
				prefix = "writeback.";
			} else {
				prefix = "response.";
			}	
		} else 
		if (typeof(joining) != "undefined" && joining) {
			mapToUse = true; // input map
			prefix = "join.";
		} else {
			prefix = "target.";
		}

		if (typeof typeOfEntry !== "undefined") {
			mapFile = getProperty(prefix + typeOfEntry + ".mapFile");
		}	

		mapEverything = false
		if (mapFile == null && typeof(responseLogFile) != "undefined") {
			// leave default map in place
			return;
		} else
		if (mapFile == null && prefix == "join.") {
			if (deBug) logmsg("--@@@ MAP @@@--> mapping everything for join")
			mapEverything = true;
			return;
		}
	}	

	if (mapFile === null && typeof typeOfEntry !== "undefined") {
		mapFile = typeOfEntry + ".map";
	}

	if (mapFile != null) {
		try {
			thisConnector.useAttributeMap(mapFile, mapToUse, true)
			if (deBug) logmsg("--@@@ MAP @@@--> using: " + mapFile)
			return
		} catch (exc) {
			// do nothing
		}
	}	

	if (mapFile == null || mapFile.length == 0 && typeof typeOfEntry !== "undefined") {
		mapFile = typeOfEntry + ".map";
	}	

	// Look first in configs, and if not found then in LDAPSync
	var testFile = null;
	mapFilePath = mapFile;
	if (mapFilePath.indexOf("/") < 0 && mapFilePath.indexOf("\\") < 0) {
		testFile = new java.io.File(configDirectory + "/" + mapFilePath);
		if (testFile.exists()) {
			mapFilePath = configDirectory + "/" + mapFile;
		}
	} 

	if (testFile === null || !testFile.exists()) {
		testFile = new java.io.File(mapFilePath);
		if (!testFile.exists()) {
			throw resource.getString("LDAPSYNC.MAP.FILE.IS.MISSING");
		}
	}	



	thisConnector.useAttributeMap(mapFilePath, mapToUse, true);
	if (deBug) logmsg("--@@@ MAP FILE @@@--> using: " + mapFilePath)
} catch (ex){
	var msg = resource.getString("LDAPSYNC.ERROR.FINDING.MAP")
	logmsg("ERROR", msg + " - " + ex + " - " + mapFile);
	addToStats(flowKey, "error","error");	

	throw (msg + " - " + ex + " - " + mapFile);
}

// reset these flags for the current entry type
abortFlow = false;
endOfData = false;

// get rdn from the old dn
//
sourceDN = work.getString("$dn")
sourceRDN = sourceDN
lookupDN = sourceDN;
opEntry["$sourceDN"] = sourceDN;
sourceLDAP = opEntry.getObject("$sourceLDAP");

// If necessary, clean up AD 'munging' of delete entry DNs
//
try {
	rdns = new javax.naming.ldap.LdapName(sourceDN).getRdns()
} catch (ex) {
	throw where() + " - " + resource.getString("LDAPSYNC.ERROR.DURING.INITIAL.PARSING.OF.SOURCE.DN") + ": " + ex + " - dn: " + sourceDN
}	
sourceRDN = rdns.get(rdns.size()-1).toString()

p = sourceRDN.indexOf("\n").toString()
if (p > 0)
	sourceRDN = sourceRDN.substring(0,p)

p = sourceRDN.indexOf("=")
sourceRDNAtt = sourceRDN.substring(0,p).trim()
sourceRDNValue = sourceRDN.substring(p+1).trim()
sourceRDN = sourceRDN.toLowerCase()

// get the sourceGUID (eg. for Active Directory entries)
sourceGUID = work.getObject(auxLinkedGUIDSourceAttribute) // AD?
if (sourceGUID != null 
	&& "objectguid".equals(auxLinkedGUIDSourceAttribute.toLowerCase())) {
	try {
		sourceGUID = system.binaryGUIDtoString(sourceGUID)
	} catch (ex) {
		sourceGUID = null
	}	
}	

if (sourceGUID === null)
	sourceGUID = ""

opEntry["$sourceGUID"] = sourceGUID;

typeOfEntry = work.getString("$typeOfEntry");
if (typeOfEntry == null) {
	typeOfEntry = "unknown";
}
opEntry["$typeOfEntry"] = typeOfEntry;

// Special case for AD with nodes like CN=Users, which are returned as type "container"
// This must be changed to OU in SDS
changeDetType = getProperty("source.changeDetectionType",null)
if ("AD".equals(changeDetType)) {
	oc = work.getAttribute("objectClass")
	if (oc != null)
		typeOfEntry = entryType(oc)

	if ("container".equals(typeOfEntry)) {
		work.setAttribute("objectClass", "organizationalUnit")
		work.setAttribute("ou", work.getString("CN"))
		sourceRDNAtt = "OU"
	}
}	

encodeRDN = true
rdnValue = null
filterDN = sourceDN

// in case of modrdn or moddn change
newSuperior = work.getString("newSuperior")
newrdn = work.getString("newrdn")

p = sourceRDNValue.indexOf("\n")
if (p > 0)
	sourceRDNValue = sourceRDNValue.substring(0,p)

// get the delta tag for this Work Entry
//
deltaOperationTag = work.getOperation()
work["$operation"] = deltaOperationTag

// detect if changeDetection & if changeLog
//
changeDetection = !("generic".equals(deltaOperationTag))
chglogMsg = work.getString("changenumber")

changeLog = (chglogMsg != null)
if (chglogMsg != null)
	chglogMsg = resource.getString("LDAPSYNC.CHANGELOG.NUMBER") + " " + chglogMsg
else
	chglogMsg = ""

// initialize this variable for use in Initialize Cycle
targetLDAPDN = null
rdnValue = null
targetEntry = null

// If this is not a change coming from a changelog Connector then there will be no
// newSuperior attribute to detect a moddn. If the sourceGUID is available then we do
// a lookup in the target to get the old DN value and compare with the current one.
// If there is a difference, then we set up the newSuperior and newrd attributes to
// allow the useDN() filtering function to handle this entry correctly
//
if ("modify".equals(deltaOperationTag) && sourceGUID !== null && sourceGUID.length > 0 && targetLDAP != null) {
	sc = system.newSearchCriteria();

	sc.addCriteria(auxLinkedGUIDAttribute, sc.EXACT, sourceGUID);
	targetLDAP.setParam("ldapReturnAttributes", auxLinkedDNAttribute +"\n" + auxLinkedGUIDAttribute + "\nsn\ncn\nobjectClass\n"+containerRDNs+targetUserRDN);
	try {
		targetEntry = targetLDAP.findEntry(sc);
	} catch (ex) {
		targetEntry = null
	}

	if (deBug) logmsg("-@@-->> (prefilter) target lookup for AD entry using " + auxLinkedGUIDAttribute + " = " + sourceGUID +
					(targetEntry === null ? " - " + resource.getString("LDAPSYNC.FAILED") : " - " + resource.getString("LDAPSYNC.SUCCESS")))

	if (targetEntry !== null) {
		targetLDAPDN = targetEntry.getString("$dn")
		previousDN = targetEntry.getString(auxLinkedDNAttribute)

		// check for change to dn, and if so then set up newrdn and newSuperior variables
		if (!previousDN.toLowerCase().equalsIgnoreCase(sourceDN.toLowerCase())) { 
			try {
				ldapName = new javax.naming.ldap.LdapName(sourceDN)
			} catch (ex) {
				throw where() + " - " + resource.getString("LDAPSYNC.ERROR.PARSING.SOURCE.DN.AFTER.TARGET.LOOKUP") + ": " + ex + " - dn: " + sourceDN
			}	
			rdns = ldapName.getRdns()
			newrdn = rdns.get(rdns.size()-1).toString()
			ldapName.remove(rdns.size()-1)
			newSuperior = ldapName.toString()
			logmsg("----->> (prefilter) " + resource.getString("LDAPSYNC.DETECTED.RENAME") + " newSuperior: " + newSuperior + "   newrdn: " + newrdn)
			// so this entry passes filtering
			filterDN = targetEntry.getString(auxLinkedDNAttribute)
		}
	}	
}

simEntry = null;

tcb = thisConnector.getFunction().getTCB();
tcb.removeAttribute("$error");
tcb.removeAttribute("$errorLogged");
passGlobalVariablesViaTCB(tcb);
if (doTiming) timing("calling WriteToTarget - before call hook")

logmsg("WARN","WARNING! - " + resource.getString("LDAPSYNC.UNABLE.TO.FIND.ENTRY.IN.TARGET.SYSTEM.UNABLE.TO.DELETE.TYPE") + typeOfEntry);
//addToStats(flowKey, typeOfEntry, "skipped", true)
addToStats(flowKey, "warn", "warn");
if (typeof(work) != "undefined" && work != null) {
	work["$status"] = "failed";
	work["$error"] = error;
}	
system.exitFlow();

change = false;
if (typeof(work) != "undefined" && work != null) {
	work["$status"] = "failed";
	work["$error"] = error;
}	
defaultInitErrorHandling("ERROR");

if (error.getString("message").indexOf("CTGDIS483E") >= 0) {
//	java.lang.System.out.println("TargetSystem connector: " + error.toString());
	error.status = "ok";
	system.ignoreEntry();
}

work["$writeStatus"] = "failed";

change = false;

// if this script is inherited into the WriteToTarget AL, then targetTCB is set to 
// the write AL. Otherwise, set it to the TCB of the current AL.
if (typeof targetTCB === "undefined") {
	targetTCB = task.getTCB();
}

updateStatusFromTCB(targetTCB, false);

if (typeof(work) != "undefined" && work != null) {
	work["$status"] = "failed";
	work["$error"] = error;
}	
defaultErrorHandling("ERROR");

logmsg(resource.getString("LDAPSYNC.INITIALIZING.CONNECTOR") + ": " + thisConnector.getName());

// set up to retrieve all membership attribute available
if (typeof filterOnGroups !== "undefined" && filterOnGroups) {
	thisConnector.connector.setParam("ldapReturnAttributes", "*\nibm-allGroups\nmemberOf\ngroupMembership");
}

