	deltaOperationTag = "delete";
}

// time to check group and attribute filters for person Entries
skipThisEntry = false;

if ("person".equals(typeOfEntry)
	&& filterOnGroups 
	&& !"delete".equals(deltaOperationTag)
	&& (sourceLDAP !== null || "AD".equalsIgnoreCase(changeDetType))
	&& !groupFiltersSatisfied(sourceLDAP, sourceDN, changeDetType, work)) {
	if (foundInTarget && !simulate) {
		logmsg("----->> " + oosMsg + ": " + resource.getString("LDAPSYNC.GROUP.FILTER")
				+ " - " + sourceDN);
		deltaOperationTag = "delete";
	} else {
		skipThisEntry = true;
		work["$writeStatus"] = "ignored";
	}
}

if (!skipThisEntry 
	&& filterOnAttributes
	&& "person".equals(typeOfEntry) 
	&& !"delete".equals(deltaOperationTag)
	&& !attributeFiltersSatisfied(work)) {
	if (foundInTarget) {
		logmsg("----->> " + oosMsg + ": " + resource.getString("LDAPSYNC.ATTRIBUTE.FILTER") 
				+ " - " + sourceDN);
		deltaOperationTag = "delete";
	} else {
		skipThisEntry = true;
		work["$writeStatus"] = "ignored";
	}	
}

dn = work.getString("$dn")

if (dn === null) {
	logmsg("ERROR", where() + " - " + resource.getString("LDAPSYNC.NO.DN.ATTRIBUTE.FOUND.IN.ENTRY.SKIPPING") 
			+ "/n" + work.toString())
	addToStats(flowKey, "error", "error");
	system.exitFlow()	
}

work["$dn"] = cleanDN(dn)

if (typeof(lastType) == "undefined") {
	lastType = ""
}

if (processRetryList || saveRetryList) {
	if (currentType != lastType) {
		retryList = new RetryList(flowKey, currentType, !isSync);
	}
}

endpointEntry = null; // initialize the source entry (used for simulate-sync reporting)
skipEntry = false

if (processRetryList) {
	// See if there are items to retry first
	retryItem = retryList.next();
	if (retryItem != null && retryItem.entry != null && retryItem.entry.size() > 0) {
		// no sourceLDAP is being set to work - will this fail? @@TODO EH
		readError = "";
		if (deBug) {
			logmsg("Retrying " + currentType + " entry for DN: " + retryItem.entry.getString("$dn"));
		}
		work.merge(retryItem.entry);

		oc = work.getAttribute("objectClass");
		typeOfEntry = entryType(oc);
		lastType = currentType;
		return;
	}
}

if (!processLiveData) {
	work.removeAllAttributes();
	return;
}

// Initialize the first time only
if (currentType != lastType || typeof(readInitialized) == "undefined" || !readInitialized) {
	readInitialized = true;

	readALFC = system.getFunction("ibmdi.AssemblyLineFC");

	readALFC.setParam("assemblyLine", ALName);
	readALFC.setParam("userComment", new java.util.Date().toString());
	readALFC.setParam("shareLog", "true");
	readALFC.setParam("mode", "2"); // Manual mode

	try {
		tcb = readALFC.getTCB();
		passGlobalVariablesViaTCB(tcb);
/*
		task.logmsg("................................ resetting the readALFC\n\n"
						+ "    al name: " + ALName + "\n\n.............................................")
*/
		opEntry["$typeOfEntry"] = typeOfEntry;
		tcb.setOperationInitParams(opEntry);
		tcb.setTaskName(flowKey + "_" + ALName + "_" + typeOfEntry);

		readALFC.initialize(null);

	} catch (ex) {
		logmsg("ERROR", ex);
		throw ex;
	}	
}

lastType = currentType;

work.removeAllAttributes();

try {
	readError = "";
	entry = null;

	entry = readALFC.perform(null);

	if (entry != null && entry.size() > 0) {
		work.merge(entry);
		work.setOperation(entry.getOperation());
		endpointEntry = system.newEntry();
		endpointEntry.merge(work);
	}

	// get the source LDAP Connector (if one exists) for later use to filter on groups
	opEntry.setAttribute("$sourceLDAP", work.getObject("$sourceLDAP"));
	opEntry.removeAttribute("$error");
	opEntry.removeAttribute("$errorLogged");
} catch (ex) {
	setException(ex, "input")

	errorMsg = flowKey + "_" + thisConnector.getName(), resource.getString("LDAPSYNC.ERROR.READING.NEXT.ENTRY.FROM.SOURCE") + " - exception: " + ex
	cname = thisConnector.getName()
	failed.put(cname, errorMsg)

	addToStats(flowKey, "error", "error");
	if (typeof(typeOfEntry) != "undefined")
		addToStats(flowKey, typeOfEntry, "error")	

	logmsg("ERROR", errorMsg)

	skipEntry = true;
	readError = errorMsg;

	addToStats(flowKey, "skipping", "skipping");
	if (typeof(typeOfEntry) != "undefined") {
		addToStats(flowKey, typeOfEntry, "skipping");
	}

	try {
		readALFC.terminate();
	} catch (ex) {
		// do nothing
	}	
	readInitialized = true;
	skipEntry = true;
	abortFlow = true;

	system.exitBranch("Loop");
}

function handleError(typeOfEntry, ex) {
	skipEntry = ifJoinFails.startsWith("abort") || ifJoinFails.startsWith("skip");

	if (ifJoinFails.startsWith("abort")) {
		errorLevel = "error";
	} else {
		errorLevel = "warning";
	}

	setException(ex, "join");

	errorMsg = flowKey + "_" + thisConnector.getName() 
				+ " - " + resource.getString("LDAPSYNC.ERROR.JOINING.DATA") 
				+ " - exception: " + ex;
	cname = thisConnector.getName();
	failed.put(cname, errorMsg);

	addToStats(flowKey, errorLevel, errorLevel);
	if (typeof(typeOfEntry) != "undefined") {
		addToStats(flowKey, typeOfEntry, errorLevel);
	}	

	logmsg(errorLevel.toUpperCase(), errorMsg);

	itr = joinALFC.keySet().iterator();
	joinALFC.get(typeOfEntry).terminate();
	joinALFC.put(typeOfEntry, "error");

	if (errorLevel == "error") {
		while (itr.hasNext()) {
			try {
				var nxt = itr.next();
				joinALFC.get(nxt).terminate();
				joinALFC.put(nxt, "error");
			} catch (ex) {
				// do nothing
			}
		}
	}	

	entry.removeAllAttributes()

	if (skipEntry) {
		readError = errorMsg
		if (ifJoinFails.startsWith("abort")) {
			abortFlow = true
			setException(readError,"fatal")
			throw errorMsg
		}

		addToStats(flowKey, "skipping", "skipping")
		if (typeof(typeOfEntry) != "undefined") {
			addToStats(flowKey, typeOfEntry, "skipping")
		}
	}
}

// --------- end of function definitions

joinEntry = null; // initialize the Join entry returned for simulate-sync reports

if (!performJoin || skipEntry || joinALFC.get(typeOfEntry) == "error") {

	if (performJoin && joinALFC.get(typeOfEntry) == "error") {
		skipEntry = ifJoinFails.startsWith("abort") || ifJoinFails.startsWith("skip");
		abortFlow = "true".equalsIgnoreCase(work.getString("$stopFlow")) || ifJoinFails.startsWith("abort");

		if (skipEntry) {
			addToStats(flowKey, "skipping", "skipping")
			if (typeof(typeOfEntry) != "undefined") {
				addToStats(flowKey, typeOfEntry, "skipping")
			}
		}
	}	
	// exit this script
	return;
}

if (joinALFC.get(typeOfEntry) == null) {
	try {
		joinALName = getALName("join." + typeOfEntry + ".AL",defaultJoinALName.get(typeOfEntry))
		if (joinALName == null || joinALName.trim().length == 0) {
			return; // leave script
		}

		var ALFC = system.getFunction("ibmdi.AssemblyLineFC")

		ALFC.setParam("assemblyLine", joinALName)
		ALFC.setParam("shareLog", "true")
		ALFC.setParam("mode", "2") // Manual mode
		joinALFC.put(typeOfEntry, ALFC)

		tcb = ALFC.getTCB();
		passGlobalVariablesViaTCB(tcb);
/*
		task.logmsg("................................ reseting the joinALFC\n\n"
						+ "    al name: " + ALName + "\n\n.............................................")
*/
		tcb.setOperationInitParams(opEntry)	
		tcb.setTaskName(flowKey + "_" + ALName + "_" + typeOfEntry + "_join")

		ALFC.initialize(null)
	} catch (ex) {
		handleError(typeOfEntry, ex)
	}	
}

try {
	readError = ""
	entry = ALFC.perform(work);

	if (entry != null && entry.size() > 0 && !entry.getObject("$skipEntry") == true) {
		var attNames = entry.getAttributeNames()
		for (var attName in attNames) {
			work.setAttribute(attName, entry.getAttribute(attName))
		}

		joinEntry = system.newEntry();
		joinEntry.merge(entry);

		abortFlow = "true".equalsIgnoreCase(work.getString("$stopFlow"));
	} else
	if (ifJoinFails.startsWith("skip")) {
		addToStats(flowKey, "skipping", "skipping");
		if (typeof(typeOfEntry) != "undefined") {
			addToStats(flowKey, typeOfEntry, "skipping");
		}
		skipEntry = true;
	} else
	if (ifJoinFails.startsWith("abort")) {
		abortFlow = true;
		skipEntry = true;
	}
} catch (ex) {
	handleError(typeOfEntry, ex)
}

if (abortFlow) {
	return; // stop processing this script
}

operation = work.getString("$operation");
simEntry = work.getObject("$simEntry");
changeDetection = !("generic".equals(work.getOperation()));
typeOfEntry = work.getString("$typeOfEntry");
status = work.getString("$writeStatus");

if ("success".equalsIgnoreCase(status)) {
	addToStats(flowKey, typeOfEntry, operation, changeDetection, work.getString("$translatedDN"));
} else
if ("skipped".equalsIgnoreCase(status) && "modify".equals(operation)) {
	addToStats(flowKey, typeOfEntry, "unchanged", changeDetection, work.getString("$translatedDN"));
}

if (simulate && typeof(simEntry) != "undefined" && simEntry !== null) {
	reportSimulateStatus(simEntry, endpointEntry, joinEntry, operation);
}

// skip the rest if simulation
if (simulate) {
	return;
}	

status = work.getString("$writeStatus");
targetLDAPDN = work.getString("$targetLDAPDN");
change = work.getObject("$change");

if ("failed".equals(status)) {

	// write to lost change file
	writeLostEntry(work, lostFileName, error.getString("message"));
} else
if ("success".equals(status) && change) {
	retryList.remove(work.getString("$dn"));
//	addToStats(flowKey, typeOfEntry, operation, false);
}

// afterwrite Hook - Launch AL if specified - already skipping at top if simulate
var entryOp = work.getString("$operation");
if (!"generic".equalsIgnoreCase(entryOp)) {
	var hookToInvoke = "afterwrite." + status + "." + typeOfEntry + "." + entryOp;
	var retEntry = invokeHook(hookToInvoke, work, resource.getString("LDAPSYNC.ERROR.CALLING.POSTWRITE.AL"));

	if (retEntry !== null && retEntry.size() > 0) {
		abortFlow = "true".equalsIgnoreCase(retEntry.getString("$stopFlow"));
	}

	if (change) {
		monitor("security");
	}
}

if (csUserMailShot && "success".equals(status) && change 
	&& "add".equalsIgnoreCase(entryOp) && "person".equalsIgnoreCase(typeOfEntry)) {
	var connEntry = work.getObject("$conn");
	csMailShot(connEntry);
}

